        0 18px 50px rgba(0,0,0,.64),
        0 5px 16px rgba(0,0,0,.40),
        inset 0 1px 0 rgba(230,185,150,.08),
        inset -18px 0 38px rgba(220,160,120,.035);
}

body.light-theme .card-left:hover{
    border-color:rgba(72,88,116,.42);
    box-shadow:
        0 14px 34px rgba(58,68,88,.22),
        0 5px 14px rgba(58,68,88,.12),
        inset 0 1px 0 rgba(255,255,255,.52);
}

body.light-theme .card-right:hover{
    border-color:rgba(132,82,48,.42);
    box-shadow:
        0 14px 34px rgba(92,58,38,.22),
        0 5px 14px rgba(92,58,38,.12),
        inset 0 1px 0 rgba(255,255,255,.50);
}

.veil-card:after{
    content:'';
    position:absolute;
    top:0;
    left:18px;
    right:18px;
    height:1px;
    pointer-events:none;
    opacity:.5;
    transform-origin:center;
    animation:edgeBreath 3.8s ease-in-out infinite;
}

.card-left:after{background:linear-gradient(90deg,transparent,rgba(190,205,230,.32),transparent)}
.card-right:after{background:linear-gradient(90deg,transparent,rgba(230,185,150,.30),transparent)}
body.light-theme .card-left:after{background:linear-gradient(90deg,transparent,rgba(70,88,120,.36),transparent)}
body.light-theme .card-right:after{background:linear-gradient(90deg,transparent,rgba(130,82,48,.34),transparent)}

.afx-lines{
    position:absolute;
    inset:0;
    z-index:0;
    pointer-events:none;
    overflow:hidden;
    opacity:.28;
}

.afx-lines .line{
    position:absolute;
    height:1px;
    width:100%;
}

.card-left .afx-lines .line{background:linear-gradient(90deg,transparent,rgba(180,190,210,.10),transparent)}
.card-right .afx-lines .line{background:linear-gradient(90deg,transparent,rgba(210,170,140,.10),transparent)}
body.light-theme .card-left .afx-lines .line{background:linear-gradient(90deg,transparent,rgba(80,95,120,.15),transparent)}
body.light-theme .card-right .afx-lines .line{background:linear-gradient(90deg,transparent,rgba(130,86,55,.15),transparent)}

.afx-lines .line:nth-child(1){top:12%;animation:lineShift 9s ease-in-out infinite}
.afx-lines .line:nth-child(2){top:28%;animation:lineShift 11s ease-in-out infinite -3s}
.afx-lines .line:nth-child(3){top:44%;animation:lineShift 8s ease-in-out infinite -5s}
.afx-lines .line:nth-child(4){top:62%;animation:lineShift 12s ease-in-out infinite -2s}
.afx-lines .line:nth-child(5){top:78%;animation:lineShift 7s ease-in-out infinite -6s}

.afx-orb{
    position:absolute;
    z-index:0;
    pointer-events:none;
    border-radius:50%;
}

.afx-o1{
    width:50%;
    height:60%;
    top:-15%;
    left:-8%;
    filter:blur(38px);
    opacity:.44;
    animation:orbFloat1 10s ease-in-out infinite;
}

.card-left .afx-o1{background:radial-gradient(ellipse,rgba(170,185,210,.08),transparent 60%)}
.card-right .afx-o1{background:radial-gradient(ellipse,rgba(210,170,140,.075),transparent 60%)}

.afx-o2{
    width:38%;
    height:45%;
    bottom:-12%;
    right:-6%;
    filter:blur(34px);
    opacity:.38;
    animation:orbFloat2 13s ease-in-out infinite;
}

.card-left .afx-o2{background:radial-gradient(ellipse,rgba(150,160,180,.055),transparent 60%)}
.card-right .afx-o2{background:radial-gradient(ellipse,rgba(180,140,110,.055),transparent 60%)}

body.light-theme .card-left .afx-o1{opacity:.34}
body.light-theme .card-left .afx-o2{opacity:.30}
body.light-theme .card-right .afx-o1{opacity:.32}
body.light-theme .card-right .afx-o2{opacity:.28}

.afx-pts{
    position:absolute;
    inset:0;
    z-index:1;
    pointer-events:none;
    overflow:hidden;
}

.card-header{
    position:relative;
    padding:14px 22px;
    cursor:pointer;
    display:flex;
    align-items:center;
    justify-content:space-between;
    transition:background .3s ease,transform .22s ease,border-color .35s ease;
    outline:none;
    -webkit-tap-highlight-color:transparent;
    flex-shrink:0;
    z-index:3;
}

.card-header:active{transform:scale(.995)}

.card-left .card-header{border-bottom:1px solid rgba(160,170,190,.12)}
.card-right .card-header{border-bottom:1px solid rgba(190,150,120,.12)}
body.light-theme .card-left .card-header{border-bottom-color:rgba(78,92,118,.26)}
body.light-theme .card-right .card-header{border-bottom-color:rgba(132,86,55,.25)}

.card-header:hover{background:rgba(255,255,255,.025)}
body.light-theme .card-header:hover{background:rgba(60,70,90,.045)}

.header-left{
    display:flex;
    align-items:center;
    gap:10px;
}

.header-right{
    display:flex;
    align-items:center;
    gap:8px;
    flex-shrink:0;
}

.card-icon{
    width:22px;
    height:22px;
    display:flex;
    align-items:center;
    justify-content:center;
    flex-shrink:0;
    opacity:.72;
    transition:opacity .3s,transform .3s ease,filter .3s ease;
    animation:iconBreath 3.2s ease-in-out infinite;
}

.card-header:hover .card-icon{
    opacity:.95;
    transform:translateY(-1px) scale(1.04);
}

.card-left .card-icon{color:#8892a4;filter:drop-shadow(0 0 6px rgba(150,170,210,.14))}
.card-right .card-icon{color:#a08878;filter:drop-shadow(0 0 6px rgba(210,170,140,.14))}
body.light-theme .card-left .card-icon{color:#3e4d66}
body.light-theme .card-right .card-icon{color:#744d34}

.card-icon svg{
    width:20px;
    height:20px;
    fill:none;
    stroke:currentColor;
    stroke-width:1.8;
    stroke-linecap:round;
    stroke-linejoin:round;
}

.header-title{
    font-size:17px;
    font-weight:760;
    letter-spacing:.04em;
    transition:color .35s ease,text-shadow .35s ease,transform .3s ease;
}

.card-header:hover .header-title{transform:translateY(-.5px)}

.card-left .header-title{color:#a8b2c4;text-shadow:0 0 12px rgba(160,180,220,.08)}
.card-right .header-title{color:#c0a898;text-shadow:0 0 12px rgba(220,170,135,.08)}
body.light-theme .card-left .header-title{color:#253246;text-shadow:none;font-weight:820}
body.light-theme .card-right .header-title{color:#4a2e20;text-shadow:none;font-weight:820}

.theme-toggle-btn{
    width:26px;
    height:26px;
    border-radius:50%;
    display:flex;
    align-items:center;
    justify-content:center;
    cursor:pointer;
    transition:all .3s ease;
    padding:0;
    outline:none;
    flex-shrink:0;
    font-size:12px;
    line-height:1;
    background:transparent;
    border:1px solid rgba(255,255,255,.1);
    color:#888;
    opacity:.55;
}

.theme-toggle-btn:hover{
    opacity:.95;
    transform:scale(1.1) rotate(12deg);
    box-shadow:0 0 12px rgba(210,180,150,.14),inset 0 1px 0 rgba(255,255,255,.055);
}

body.light-theme .theme-toggle-btn{
    border-color:rgba(45,55,72,.22);
    color:#293342;
    opacity:.72;
}

.arrow-indicator{
    width:26px;
    height:26px;
    border-radius:50%;
    display:flex;
    align-items:center;
    justify-content:center;
    transition:all .4s cubic-bezier(.175,.885,.32,1.275);
    flex-shrink:0;
    opacity:.48;
}

.card-left .arrow-indicator{color:#8892a4}
.card-right .arrow-indicator{color:#a08878}
body.light-theme .card-left .arrow-indicator{color:#35445c}
body.light-theme .card-right .arrow-indicator{color:#70472f}

.veil-card.expanded .arrow-indicator{
    transform:scale(1.08) rotate(360deg);
    opacity:.78;
}

.arrow-indicator svg{
    width:15px;
    height:15px;
    fill:none;
    stroke:currentColor;
    stroke-width:2;
    stroke-linecap:round;
    stroke-linejoin:round;
    transition:transform .4s cubic-bezier(.175,.885,.32,1.275);
}

.veil-card.expanded .arrow-indicator svg{transform:rotate(180deg)}

.card-content{
    display:grid;
    grid-template-rows:0fr;
    overflow:hidden;
    transition:grid-template-rows .46s cubic-bezier(.4,0,.2,1),opacity .3s ease,filter .3s ease;
    position:relative;
    z-index:3;
    opacity:0;
    filter:blur(2px);
    will-change:grid-template-rows,opacity;
}

.veil-card.expanded .card-content{
    grid-template-rows:1fr;
    opacity:1;
    filter:blur(0);
}

.card-content-inner{
    min-height:0;
    overflow:hidden;
    transform:translateY(-8px);
    transition:transform .42s cubic-bezier(.18,.89,.32,1.12);
}

.veil-card.expanded .card-content-inner{
    overflow-y:auto;
    transform:translateY(0);
    max-height:4000px;
}

.card-left .card-content-inner{
    background-image:repeating-linear-gradient(to bottom,transparent,transparent 1.55rem,rgba(160,170,190,.03) 1.55rem,rgba(160,170,190,.03) 1.6rem);
}
.card-right .card-content-inner{
    background-image:repeating-linear-gradient(to bottom,transparent,transparent 1.55rem,rgba(190,150,120,.03) 1.55rem,rgba(190,150,120,.03) 1.6rem);
}
body.light-theme .card-left .card-content-inner{
    background-image:repeating-linear-gradient(to bottom,transparent,transparent 1.55rem,rgba(60,75,100,.065) 1.55rem,rgba(60,75,100,.065) 1.6rem);
}
body.light-theme .card-right .card-content-inner{
    background-image:repeating-linear-gradient(to bottom,transparent,transparent 1.55rem,rgba(120,78,48,.065) 1.55rem,rgba(120,78,48,.065) 1.6rem);
}

.card-content-inner::-webkit-scrollbar{width:3px}
.card-content-inner::-webkit-scrollbar-track{background:transparent}
.card-content-inner::-webkit-scrollbar-thumb{border-radius:2px}
.card-left .card-content-inner::-webkit-scrollbar-thumb{background:rgba(160,170,190,.16)}
.card-right .card-content-inner::-webkit-scrollbar-thumb{background:rgba(190,150,120,.16)}

.content-body{
    padding:18px 22px 26px;
    font-size:14px;
    font-weight:430;
    white-space:pre-wrap;
    word-wrap:break-word;
    word-break:break-word;
    overflow-wrap:break-word;
    transition:color .35s ease,opacity .42s ease,transform .42s cubic-bezier(.18,.89,.32,1.12);
    letter-spacing:.02em;
    line-height:1.85;
    opacity:0;
    transform:translateY(-5px);
}

.veil-card.expanded .content-body{
    opacity:1;
    transform:translateY(0);
}

.card-left .content-body{color:#bcc4d2}
.card-right .content-body{color:#d4c4b8}

/* 日间正文重点优化 */
body.light-theme .card-left .content-body{
    color:#202837;
    font-size:14.5px;
    font-weight:500;
    line-height:1.9;
    text-shadow:0 1px 0 rgba(255,255,255,.35);
}

body.light-theme .card-right .content-body{
    color:#342318;
    font-size:14.5px;
    font-weight:500;
    line-height:1.9;
    text-shadow:0 1px 0 rgba(255,255,255,.32);
}

.card-content-inner:after{
    content:'';
    position:sticky;
    display:block;
    bottom:0;
    height:42px;
    margin-top:-42px;
    pointer-events:none;
}

.card-left .card-content-inner:after{background:linear-gradient(to bottom,transparent,rgba(22,24,30,.92))}
.card-right .card-content-inner:after{background:linear-gradient(to bottom,transparent,rgba(26,22,20,.92))}
body.light-theme .card-left .card-content-inner:after{background:linear-gradient(to bottom,transparent,rgba(214,220,230,.96))}
body.light-theme .card-right .card-content-inner:after{background:linear-gradient(to bottom,transparent,rgba(226,210,196,.96))}

.center-connector{
    display:flex;
    align-items:center;
    justify-content:center;
    width:0;
    position:relative;
    z-index:10;
    flex-shrink:0;
}

.connector-orb{
    width:6px;
    height:6px;
    border-radius:50%;
    background:rgba(180,160,145,.78);
    box-shadow:0 0 5px rgba(210,190,170,.65),0 0 16px rgba(210,190,170,.28),0 0 36px rgba(210,190,170,.12);
    animation:orbPulse 4s ease-in-out infinite;
    position:absolute;
}

.ax-p{
    position:absolute;
    pointer-events:none;
    z-index:2;
    will-change:transform,opacity;
}

.particle-dot{
    border-radius:50%;
    animation:particleFloat var(--pdur,8s) ease-in-out infinite;
    animation-delay:var(--pdel,0s);
    opacity:0;
}

.card-left .particle-dot{
    background:radial-gradient(circle,rgba(190,200,220,.68) 0%,rgba(170,180,200,.22) 40%,transparent 70%);
    box-shadow:0 0 5px rgba(180,195,215,.35);
}

.card-right .particle-dot{
    background:radial-gradient(circle,rgba(210,180,150,.68) 0%,rgba(190,160,130,.22) 40%,transparent 70%);
    box-shadow:0 0 5px rgba(200,170,140,.35);
}

.particle-line{
    width:1px;
    animation:particleLine var(--pdur,10s) ease-in-out infinite;
    animation-delay:var(--pdel,0s);
    opacity:0;
    transform-origin:top center;
}

.card-left .particle-line{background:linear-gradient(180deg,rgba(180,195,215,.56),transparent)}
.card-right .particle-line{background:linear-gradient(180deg,rgba(200,170,140,.56),transparent)}

@media(max-width:720px){
    .dual-cards-wrapper{flex-direction:column}
    .veil-card{width:100%}
    .card-left{
        border-radius:14px 14px 0 0;
        border-right:1px solid rgba(140,150,170,.2);
        border-bottom:1px dashed rgba(180,170,160,.18);
    }
    .card-right{
        border-radius:0 0 14px 14px;
        border-left:1px solid rgba(170,140,120,.2);
        border-top:1px dashed rgba(180,170,160,.18);
    }
    .center-connector{width:100%;height:0}
    .card-header{padding:12px 16px}
    .header-title{font-size:15px}
    .content-body{padding:15px 16px 26px;font-size:13.5px}
    body.light-theme .content-body{font-size:14px}
    .afx-lines .line:nth-child(n+4){display:none}
    .particle-line{display:none}
    .particle-dot:nth-child(n+9){display:none}
    .card-content{filter:none}
    .veil-card.expanded .card-content{filter:none}
    .card-left,.card-right{
        backdrop-filter:blur(6px);
        -webkit-backdrop-filter:blur(6px);
    }
}

@media(prefers-reduced-motion:reduce){
    *,*:before,*:after{
        animation:none!important;
        transition-duration:.12s!important;
    }
    .ax-p{display:none!important}
}

@keyframes orbPulse{
    0%,100%{transform:scale(1);opacity:.4}
    15%{transform:scale(2);opacity:1}
    30%{transform:scale(1);opacity:.4}
    45%{transform:scale(1.6);opacity:.7}
    60%{transform:scale(1);opacity:.35}
}
@keyframes particleFloat{
    0%,100%{transform:translateY(0) translateX(0) scale(1);opacity:0}
    10%{opacity:var(--popeak,.5)}
    40%{transform:translateY(-12px) translateX(var(--pdx,3px)) scale(1.3);opacity:var(--popeak,.5)}
    60%{transform:translateY(-6px) translateX(calc(var(--pdx,3px)*-.5)) scale(.9);opacity:calc(var(--popeak,.5)*.3)}
    90%{opacity:0}
}
@keyframes particleLine{
    0%,100%{transform:scaleY(.2);opacity:0}
    15%{opacity:var(--popeak,.4)}
    45%{transform:scaleY(1);opacity:var(--popeak,.4)}
    70%{transform:scaleY(.6);opacity:calc(var(--popeak,.4)*.2)}
    95%{opacity:0}
}
@keyframes lineShift{
    0%,100%{opacity:.3;transform:translateX(0)}
    25%{opacity:.65;transform:translateX(2%)}
    50%{opacity:.25;transform:translateX(-1%)}
    75%{opacity:.58;transform:translateX(1.5%)}
}
@keyframes orbFloat1{
    0%,100%{transform:translate(0,0) scale(1)}
    33%{transform:translate(35%,25%) scale(1.2)}
    66%{transform:translate(12%,45%) scale(.85)}
}
@keyframes orbFloat2{
    0%,100%{transform:translate(0,0) scale(1)}
    40%{transform:translate(-25%,-15%) scale(1.25)}
    70%{transform:translate(-10%,-35%) scale(.9)}
}
@keyframes edgeBreath{
    0%,100%{opacity:.35;transform:scaleX(.78)}
    50%{opacity:.85;transform:scaleX(1)}
}
@keyframes iconBreath{
    0%,100%{transform:translateY(0) scale(1)}
    50%{transform:translateY(-1px) scale(1.035)}
}
</style>
</head>

<body class="dark-theme">
<div id="rawText" style="display:none;">$1</div>

<div class="dual-cards-wrapper">
    <div class="veil-card card-left" id="leftCard">
        <div class="afx-lines">
            <div class="line"></div><div class="line"></div><div class="line"></div><div class="line"></div><div class="line"></div>
        </div>
        <div class="afx-orb afx-o1"></div>
        <div class="afx-orb afx-o2"></div>
        <div class="afx-pts" id="leftParticles"></div>

        <div class="card-header" id="leftHeader" role="button" tabindex="0" aria-expanded="false">
            <div class="header-left">
                <div class="card-icon">
                    <svg viewBox="0 0 24 24">
                        <rect x="5" y="5" width="14" height="14" rx="2" transform="rotate(45 12 12)"/>
                    </svg>
                </div>
                <span class="header-title">表</span>
            </div>
            <div class="header-right">
                <div class="arrow-indicator">
                    <svg viewBox="0 0 24 24"><polyline points="6 9 12 15 18 9"/></svg>
                </div>
            </div>
        </div>

        <div class="card-content" id="leftContent">
            <div class="card-content-inner">
                <div class="content-body" id="leftDisplay"></div>
            </div>
        </div>
    </div>

    <div class="center-connector"><div class="connector-orb"></div></div>

    <div class="veil-card card-right" id="rightCard">
        <div class="afx-lines">
            <div class="line"></div><div class="line"></div><div class="line"></div><div class="line"></div><div class="line"></div>
        </div>
        <div class="afx-orb afx-o1"></div>
        <div class="afx-orb afx-o2"></div>
        <div class="afx-pts" id="rightParticles"></div>

        <div class="card-header" id="rightHeader" role="button" tabindex="0" aria-expanded="false">
            <div class="header-left">
                <div class="card-icon">
                    <svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="7"/></svg>
                </div>
                <span class="header-title">裏</span>
            </div>
            <div class="header-right">
                <button class="theme-toggle-btn" id="themeToggleBtn" title="切换日夜模式">◐</button>
                <div class="arrow-indicator">
                    <svg viewBox="0 0 24 24"><polyline points="6 9 12 15 18 9"/></svg>
                </div>
            </div>
        </div>

        <div class="card-content" id="rightContent">
            <div class="card-content-inner">
                <div class="content-body" id="rightDisplay"></div>
            </div>
        </div>
    </div>
</div>

<script>
(function(){
    var rawText=document.getElementById('rawText').textContent.trim();
    var leftText=rawText;
    var rightText='';
    var idx=rawText.indexOf('[OS]');

    if(idx!==-1){
        leftText=rawText.substring(0,idx).trim();
        rightText=rawText.substring(idx+4).trim();
    }

    document.getElementById('leftDisplay').textContent=leftText;
    document.getElementById('rightDisplay').textContent=rightText;

    var body=document.body;
    var leftCard=document.getElementById('leftCard');
    var leftHeader=document.getElementById('leftHeader');
    var leftExpanded=false;

    var rightCard=document.getElementById('rightCard');
    var rightHeader=document.getElementById('rightHeader');
    var rightExpanded=false;

    var themeToggleBtn=document.getElementById('themeToggleBtn');

    function toggleCard(card,header,getExp,setExp){
        return function(e){
            if(e)e.stopPropagation();
            if(getExp()){
                card.classList.remove('expanded');
                setExp(false);
                header.setAttribute('aria-expanded','false');
            }else{
                card.classList.add('expanded');
                setExp(true);
                header.setAttribute('aria-expanded','true');
            }
        };
    }

    leftHeader.addEventListener('click',toggleCard(leftCard,leftHeader,function(){return leftExpanded},function(v){leftExpanded=v}));
    rightHeader.addEventListener('click',toggleCard(rightCard,rightHeader,function(){return rightExpanded},function(v){rightExpanded=v}));

    leftHeader.addEventListener('keydown',function(e){
        if(e.key==='Enter'||e.key===' '){
            e.preventDefault();
            leftHeader.click();
        }
    });

    rightHeader.addEventListener('keydown',function(e){
        if(e.key==='Enter'||e.key===' '){
            e.preventDefault();
            rightHeader.click();
        }
    });

    function applyTheme(t){
        if(t==='light'){
            body.classList.add('light-theme');
            body.classList.remove('dark-theme');
            try{localStorage.setItem('fox-preset-theme','light')}catch(e){}
        }else{
            body.classList.remove('light-theme');
            body.classList.add('dark-theme');
            try{localStorage.setItem('fox-preset-theme','dark')}catch(e){}
        }
    }

    var st=null;
    try{st=localStorage.getItem('fox-preset-theme')}catch(e){}

    if(st==='light'||st==='day')applyTheme('light');
    else if(st==='dark'||st==='night')applyTheme('dark');
    else applyTheme('dark');

    themeToggleBtn.addEventListener('click',function(e){
        e.stopPropagation();
        if(body.classList.contains('light-theme'))applyTheme('dark');
        else applyTheme('light');
    });

    function rr(a,b){return a+Math.random()*(b-a)}

    function spawnParticles(container){
        var isMob=window.innerWidth<720;
        var dots=isMob?8:15;
        var lines=isMob?0:5;

        for(var i=0;i<dots;i++){
            var dot=document.createElement('div');
            dot.className='ax-p particle-dot';
            var size=rr(1.5,4);
            dot.style.width=size+'px';
            dot.style.height=size+'px';
            dot.style.left=rr(5,90)+'%';
            dot.style.top=rr(10,85)+'%';
            dot.style.setProperty('--pdur',rr(6,14)+'s');
