  // 处理单个楼层：按「推理标签提取器」的逻辑，把原生推理中
  // <content>…</content> 之间最后一个完整块（含标签）移到正文末尾。
  // force=true 时忽略「自动提取」开关，供手动处理使用。
  async function ssRescueProcessMessage(e, { force = false } = {}) {
    const t = ssReadContentRescueSettings();
    if (!force && !t.enabled) return { count: 0, reason: "自动提取已关闭" };

    const msg = ssGetRawChatMessage(e);
    if (!msg) return { count: 0, reason: `楼层不存在(${e})` };

    const swipe_id = msg.swipe_id ?? 0;
    const sources = ssCollectReasoningSources(msg, swipe_id);
    if (sources.length === 0) return { count: 0, reason: "推理内容为空" };

    let captured = [];
    let remaining = "";
    let used_source = null;
    let missing_end = false;
    for (const source of sources) {
      let working = source.text;
      const segments = [];
      for (const pair of t.pairs) {
        if (pair.start) {
          // 贪婪匹配：开始标签取最后一个，吃掉前面思考中字面出现的同名标签
          const lastIdx = working.lastIndexOf(pair.start);
          if (lastIdx === -1) continue;
          const after = working.slice(lastIdx + pair.start.length);
          let full = "";
          let consumedEnd = working.length;
          if (pair.end) {
            // 贪婪匹配：结束标签同样取最后一个，一直吃到最底部的结束标签
            const endIdx = after.lastIndexOf(pair.end);
            if (endIdx === -1) {
              missing_end = true;
              continue;
            }
            full = pair.start + after.slice(0, endIdx) + pair.end;
            consumedEnd =
              lastIdx + pair.start.length + endIdx + pair.end.length;
          } else {
            full = pair.start + after;
          }
          working = working.slice(0, lastIdx) + working.slice(consumedEnd);
          if (full.trim()) segments.push(full.trim());
        } else if (pair.end) {
          // 只配置结束标签：取最底部结束标签之前的一切内容
