      return {
        count: 0,
        reason: missing_end
          ? "未找到结束标签(推理文本中不存在已配置的结束标签)"
          : "未发现匹配的标签",
      };
    }

    // 移入正文末尾（同步更新 swipes，避免切换消息页后丢失）
    const addition = "\n" + captured.join("\n");
    msg.mes = (msg.mes || "") + addition;
    if (Array.isArray(msg.swipes)) {
      msg.swipes[swipe_id] = msg.mes;
    }

    // 清理剩余推理：仅压缩空行，其余原样保留
    const clean = ssRescueStripLeftoverTags(remaining);

    // 回写推理：只更新与「提取来源」文本一致的字段
