  async function ssRunSummaryWithRetry(summaryFn, label) {
    const maxRetries = S.summaryAutoRetryEnabled
      ? S.summaryAutoRetryCount || 3
      : 1;
    let lastError = null;
    for (let attempt = 1; attempt <= maxRetries; attempt++) {
      if (!S.isSummarizing) {
        throw new Error("用户取消");
      }
      if (attempt > 1) {
        const delay = 2000 * attempt;
        log(
          `[大总结重试] ${label} 第 ${attempt}/${maxRetries} 次重试，等待 ${delay}ms`,
        );
        toast(`🔄 ${label}第 ${attempt} 次重试中…`, "info");
        await new Promise((r) => setTimeout(r, delay));
      }
      if (!S.isSummarizing) {
        throw new Error("用户取消");
      }
      try {
        const success = await summaryFn();
        if (success) {
          if (attempt > 1) {
            toast(`✅ ${label}第 ${attempt} 次重试成功`, "success");
          }
          return true;
        }
        lastError = new Error("总结返回空内容或失败");
        log(
          `[大总结重试] ${label} 第 ${attempt} 次返回失败`,
          lastError.message,
        );
      } catch (e) {
        const msg = e?.message || String(e || "");
        if (/abort|aborted|cancel|取消|中断/i.test(msg)) {
          log(`[大总结重试] ${label} 被用户中断，停止重试`);
          throw e;
        }
        lastError = e;
        log(`[大总结重试] ${label} 第 ${attempt} 次异常`, msg);
      }
    }
    const errMsg = lastError?.message || String(lastError || "未知错误");
    log(`[大总结重试] ${label} 全部 ${maxRetries} 次重试失败`, errMsg);
    throw new Error(`${label}失败（已重试 ${maxRetries} 次）：${errMsg}`);
  }
