  async function generateSummaryChunk(e, t, n, o, a = {}) {
    const r = 3;
    let s = null;
    let retryCount = 0;
    for (let i = 1; i <= r; i++) {
      retryCount = i;
      try {
        const r = await generateSummaryChunkOnce(e, t, n, o, i, a);
        if (String(r || "").trim()) {
          if (i > 1) {
            toast(`✅ 第 ${n}/${o} 段总结第 ${i} 次重试成功`, "success");
          }
          return {
            text: String(r || "").trim(),
            success: true,
            chunkIndex: n,
            totalChunks: o,
            retryCount: i,
            error: null,
          };
        }
        s = new Error(`第 ${n}/${o} 段第 ${i} 次返回空内容`);
        log("[大总结兜底] 空回，准备重试", s.message);
      } catch (e) {
        const t = e?.message || String(e || "");
        if (/abort|aborted|cancel|取消|中断/i.test(t)) {
          throw e;
        }
        s = e;
        log(`[大总结兜底] 第 ${n}/${o} 段第 ${i} 次失败，准备重试`, e);
      }
      await new Promise((e) => setTimeout(e, 900 + i * 500));
    }
    const i = String(t || "").trim();
    const l = `\n\n【自动兜底提示】\n第 ${n}/${o} 段总结连续 ${r} 次请求失败或空回。\n玄狐已保留前面已经完成的总结，并跳过该分块，避免整个全文大总结任务被砍死。\n建议稍后重新点击“全文大总结”补全该分块。\n错误信息：${s?.message || s || "未知空回"}`;
    toast(`⚠️ 第 ${n}/${o} 段连续空回，已跳过该段并继续后续总结`, "warning");
    let fallbackText;
    if (i) {
      fallbackText = `${i}${l}`.trim();
    } else {
      fallbackText = `<details>\n<summary>大总结</summary>\n\n${l.trim()}\n\n</details>\n\n<char_date>\n（因模型连续空回，本段未能生成角色状态总结。）\n</char_date>`;
    }
    return {
      text: fallbackText,
      success: false,
      chunkIndex: n,
      totalChunks: o,
      retryCount: retryCount,
      error: s,
    };
  }
