-radius:10px;border:1px solid rgba(255,255,255,.1);background:rgba(255,255,255,.04);color:#8a7f78;cursor:pointer;font-size:13px;display:flex;align-items:center;justify-content:center;flex-shrink:0;transition:all .15s}\n#ss-outline-panel .mb-dock{flex-shrink:0;background:rgba(8,6,5,.96);backdrop-filter:blur(14px);border-top:1px solid rgba(232,120,74,.18);display:flex;align-items:stretch;justify-content:space-around;padding:5px 4px calc(5px + env(safe-area-inset-bottom));position:relative;z-index:10}\n#ss-outline-panel .mb-dock::before{content:"";position:absolute;left:10%;right:10%;top:0;height:1px;background:linear-gradient(90deg,transparent,rgba(232,120,74,.38),transparent)}\n#ss-outline-panel .dock-item{flex:1;max-width:88px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;padding:6px 4px 4px;border-radius:11px;cursor:pointer;transition:all .2s;position:relative;border:1px solid transparent}\n#ss-outline-panel .dock-item.cur{background:linear-gradient(180deg,rgba(232,120,74,.16),rgba(232,120,74,.03));border-color:rgba(232,120,74,.32)}\n#ss-outline-panel .dock-item.cur::after{content:"";position:absolute;top:-1px;left:25%;right:25%;height:2px;border-radius:99px;background:linear-gradient(90deg,#e8784a,#f0a070);box-shadow:0 0 8px rgba(232,120,74,.7)}\n#ss-outline-panel .dock-item .d-ic{font-size:17px;line-height:1;display:flex;align-items:center;justify-content:center;width:28px;height:28px;border-radius:8px}\n#ss-outline-panel .dock-item.cur .d-ic{background:linear-gradient(135deg,rgba(232,120,74,.35),rgba(240,160,112,.15));box-shadow:0 0 10px rgba(232,120,74,.3)}\n#ss-outline-panel .dock-item .d-t{font-size:9.5px;color:#706058;font-weight:500}\n#ss-outline-panel .dock-item.cur .d-t{color:#f0a070;text-shadow:0 0 8px rgba(232,120,74,.4)}\n#ss-outline-panel .ol-cfg{grid-template-columns:1fr!important}\n}\n</style>\n<div class="mb-top">\n  <button class="mb-back" id="outline-close">‹</button>\n  <div class="mb-title"><h1>🏗️ 狐构</h1><p id="ol-mb-sub">大纲 · 内容 · 生成</p></div>\n  <div class="mb-right"><button class="mb-ic" id="outline-save-bottom-btn-mb">💾</button></div>\n</div>\n<div class="pc-head">\n  <div class="crumb">🦊 模块中心 <i>▸</i> <b>🏗️ 狐构</b></div>\n  <div class="hd-right"><span class="hd-pill"><b>剧情大纲</b></span></div>\n  <button class="btn-x" id="outline-close-pc">✕</button>\n</div>\n<div class="work">\n  <aside class="rail">\n    <div class="rl-title">狐构 模块</div>\n    <div class="mitem cur" data-oltab="ov"><span class="mico">🗺️</span><div class="mtext"><b>大纲</b><small>内容 · 生成 · 候选</small></div></div>\n    <div class="rl-sec">配置</div>\n    <div class="mitem" data-oltab="cfg"><span class="mico">⚙️</span><div class="mtext"><b>API · 注入</b><small>自定义模型</small></div></div>\n    <div class="mitem" data-oltab="adv"><span class="mico">🔄</span><div class="mtext"><b>修正 · 过滤</b><small>动态分析 · 过滤</small></div></div>\n    <div class="stat-mini">\n      <div class="sm-label">● 大纲状态</div>\n      <div class="sm-grid">\n        <div class="sm-item green"><span class="vl" id="ol-stat-nodes">-</span><span class="lb">节点数</span></div>\n        <div class="sm-item"><span class="vl" id="ol-stat-progress">-</span><span class="lb">进度</span></div>\n      </div>\n    </div>\n  </aside>\n  <main class="main">\n    <section class="ol-tab-pane active" data-olpane="ov">\n      <div class="m-head"><span class="mico">🗺️</span><h2>大纲 · 内容与生成</h2></div>\n      <div class="quick-bar">\n        <button class="ol-vbtn ol-vbtn-primary" id="outline-save-bottom-btn">💾 保存大纲</button>\n      </div>\n      <div class="ol-vcard">\n        <div class="ol-vcard-header"><h3>📋 大纲内容</h3></div>\n        <div id="ss-outline-mgmt-mask" style="display:flex;align-items:center;justify-content:center;height:80px;border:1px dashed rgba(232,120,74,0.2);border-radius:8px;margin-bottom:8px;cursor:pointer;">\n          <span style="color:#706058;font-size:12px;">🔒 点击此处查看/编辑大纲（剧透警告）</span>\n        </div>\n        <textarea id="ss-outline-edit-textarea" placeholder="大纲内容..." style="width:100%;min-height:180px;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.2);border-radius:8px;color:#e8ddd4;padding:10px;font-size:12px;font-family:monospace;resize:vertical;box-sizing:border-box;display:none;"></textarea>\n        <div id="ss-outline-edit-btns" style="display:none;gap:8px;margin-top:8px;">\n          <button id="outline-refresh-btn" class="ol-vbtn ol-vbtn-ghost" style="flex:1">🔄 刷新</button>\n          <button id="outline-save-btn" class="ol-vbtn ol-vbtn-primary" style="flex:1">💾 保存</button>\n          <button id="outline-clear-btn" class="ol-vbtn ol-vbtn-danger" style="flex:1">🗑️ 清除</button>\n        </div>\n      </div>\n      <div class="ol-vcard" style="font-size:12px;color:#f0a070;line-height:1.6;">\n        🦊 唔……建议先用🦊狐析分析完偏好后，再进行大纲撰写……这样的话，大纲就会根据你的偏好进行整体撰写哦～\n      </div>\n      <div class="ol-vcard">\n        <div class="ol-vcard-header"><h3>📝 用户补充与生成参数</h3></div>\n        <textarea id="outline-user-input" placeholder="不想填也可以直接生成哦～写了的话AI会结合你的想法来撰写大纲～" style="width:100%;min-height:60px;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.2);border-radius:8px;color:#e8ddd4;padding:8px;font-size:12px;resize:vertical;box-sizing:border-box;font-family:inherit;">${escapeHtml(S.outlineUserCorrection)}</textarea>\n        <div style="display:flex;gap:8px;margin-top:8px;align-items:center;flex-wrap:wrap;">\n          <label style="display:flex;align-items:center;gap:4px;font-size:12px;color:#a09088;">📋 生成数量<input id="outline-count-input" type="number" min="1" max="10" value="${S.outlineCount}" style="width:50px;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.2);border-radius:6px;color:#e8ddd4;padding:4px 6px;font-size:12px;">个</label>\n          <label style="display:flex;align-items:center;gap:4px;font-size:12px;color:#a09088;">📏 字数限制<input id="outline-word-limit-input" type="text" value="${escapeHtml(S.outlineWordLimit)}" placeholder="300-1200" style="width:80px;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.2);border-radius:6px;color:#e8ddd4;padding:4px 6px;font-size:12px;">字</label>\n          <label style="display:flex;align-items:center;gap:4px;font-size:12px;color:#a09088;">📚 分析最近<input id="outline-analysis-floors" type="number" min="0" value="${S.outlineAnalysisFloors}" style="width:70px;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.2);border-radius:6px;color:#e8ddd4;padding:4px 6px;font-size:12px;">楼</label>\n          <span style="font-size:11px;color:#706058;">0=全部；仍有输入安全上限</span>\n        </div>\n        <label style="display:flex;align-items:center;gap:6px;margin-top:8px;font-size:12px;color:#d8a080;cursor:pointer;">\n          <input type="checkbox" id="outline-no-spoiler-warning" ${S.outlineNoSpoilerWarning ? "checked" : ""}>\n          ⚠️无防剧透提醒\n        </label>\n        <div style="display:flex;gap:8px;margin-top:8px;">\n          <button id="outline-generate-btn" class="ol-vbtn ol-vbtn-primary" style="flex:1">📝 生成大纲</button>\n          <button id="outline-correct-btn" class="ol-vbtn ol-vbtn-ghost" style="flex:1">🔄 动态修正（根据当前剧情修正大纲）</button>\n        </div>\n        <div style="display:flex;gap:8px;margin-top:8px;align-items:flex-start;">\n          <textarea id="outline-manual-correct-input" placeholder="手动修正：直接输入你的修正要求（例如：把第三章改成主角先回城再复仇），点击右侧按钮立即修正大纲～" style="flex:1;min-height:60px;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.2);border-radius:8px;color:#e8ddd4;padding:8px;font-size:12px;resize:vertical;box-sizing:border-box;font-family:inherit;">${escapeHtml(S.outlineManualCorrection || "")}</textarea>\n          <button id="outline-manual-correct-btn" class="ol-vbtn ol-vbtn-ghost" style="flex-shrink:0;align-self:stretch;">✍️ 手动修正</button>\n        </div>\n      </div>\n      <div class="ol-vcard" style="margin-bottom:0">\n        <div class="ol-vcard-header"><h3>📝 候选大纲</h3></div>\n        <div id="ss-outline-candidates" style="display:flex;flex-direction:column;gap:10px;max-height:50vh;overflow-y:auto;"></div>\n      </div>\n    </section>\n    <section class="ol-tab-pane" data-olpane="cfg">\n      <div class="m-head"><span class="mico">⚙️</span><h2>API配置 · 注入方式</h2></div>\n      <div class="ol-vcard">\n        <div class="ol-vcard-header"><h3>📦 狐构注入方式</h3></div>\n        <label class="ol-switch-row" style="border:1px solid rgba(255,170,90,0.42);background:linear-gradient(90deg,rgba(232,120,74,0.16),rgba(255,255,255,0.025));margin-bottom:8px;">\n          <span class="info">\n            <strong style="color:#ffb06a;">📌 插入到当前提示词（推荐）</strong>\n            <small>打开后，大纲只跟随本次请求一起给 AI 看；换卡、换聊天不污染预设。</small>\n          </span>\n          <input id="outline-inject-current-toggle" type="checkbox" ${S.outlineInjectCurrentPrompt ? "checked" : ""} style="cursor:pointer;width:18px;height:18px;">\n        </label>\n        <label class="ol-switch-row" style="border:1px solid rgba(232,120,74,0.12);background:rgba(255,255,255,0.02);">\n          <span class="info">\n            <b>💾 注入到预设（慎用）</b>\n            <small>会写进预设条目。换卡/换聊天前如果忘记清理，可能串大纲。</small>\n          </span>\n          <input id="outline-inject-preset-toggle" type="checkbox" ${S.outlineInjectToPreset ? "checked" : ""} style="cursor:pointer;width:16px;height:16px;">\n        </label>\n      </div>\n      <div class="ol-vcard" style="margin-bottom:0">\n        <div class="ol-vcard-header"><h3>🤖 分析 API 配置</h3></div>\n        <div class="ol-cfg">\n          <label>API 来源\n            <select id="outline-api-type">\n              <option value="main" ${o.apiType === "main" ? "selected" : ""}>酒馆当前 API</option>\n              <option value="custom" ${o.apiType === "custom" ? "selected" : ""}>自定义 OpenAI 兼容 API</option>\n            </select>\n          </label>\n          <div id="outline-preset-mode-wrap" style="display:${a ? "block" : "none"};">\n            <label>预设模式\n              <select id="outline-preset-mode">\n                <option value="custom" ${!o.customApi.proxyPreset ? "selected" : ""}>直接配置</option>\n                <option value="proxy" ${o.customApi.proxyPreset ? "selected" : ""}>借用酒馆代理预设</option>\n              </select>\n            </label>\n          </div>\n        </div>\n        <div id="outline-custom-api-section" style="display:${a ? "block" : "none"};margin-top:10px;">\n          <div id="outline-proxy-section" style="display:${o.customApi.proxyPreset ? "block" : "none"};">\n            <label style="font-size:11px;color:#706058;">目标代理预设</label>\n            <select id="outline-proxy-preset" style="width:100%;box-sizing:border-box;">${s}</select>\n          </div>\n          <div id="outline-direct-section" style="display:${!o.customApi.proxyPreset ? "block" : "none"};">\n            <div class="ol-cfg">\n              <label>API 地址<input id="outline-api-url" type="text" value="${escapeHtml(o.customApi.apiurl || "")}" style="width:100%;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.15);border-radius:6px;color:#e8ddd4;padding:5px 8px;font-size:12px;"></label>\n              <label>API Key<input id="outline-api-key" type="password" value="${escapeHtml(o.customApi.key || "")}" style="width:100%;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.15);border-radius:6px;color:#e8ddd4;padding:5px 8px;font-size:12px;"></label>\n            </div>\n          </div>\n          <div class="ol-cfg" style="margin-top:8px;">\n            <label>模型\n              <div style="display:flex;gap:6px;">\n                <input id="outline-api-model" type="text" value="${escapeHtml(o.customApi.model || "")}" style="flex:1;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.15);border-radius:6px;color:#e8ddd4;padding:5px 8px;font-size:12px;">\n                <button id="outline-fetch-models" class="ol-vbtn ol-vbtn-ghost" style="white-space:nowrap">${S.outlineLoading ? "加载中…" : "获取"}</button>\n              </div>\n            </label>\n            <label>模型列表\n              <select id="outline-api-model-select" style="width:100%;">${i}</select>\n            </label>\n          </div>\n          <details style="margin-top:10px;border:1px solid rgba(232,120,74,0.12);border-radius:8px;background:rgba(255,255,255,0.02);">\n            <summary style="cursor:pointer;padding:8px 10px;color:#f0a070;font-size:12px;font-weight:600;user-select:none;">⚙️ 高级参数</summary>\n            <div class="ol-cfg" style="padding:10px;">\n              <label>温度<input id="outline-api-temp" type="number" min="0" max="2" step="0.1" value="${escapeHtml(o.customApi.temperature ?? "")}" style="width:100%;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.15);border-radius:6px;color:#e8ddd4;padding:5px 8px;font-size:12px;"></label>\n              <label>最大 token<input id="outline-api-max-tokens" type="number" min="0" step="128" value="${escapeHtml(o.customApi.max_tokens ?? "")}" style="width:100%;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.15);border-radius:6px;color:#e8ddd4;padding:5px 8px;font-size:12px;"></label>\n              <label>Top P<input id="outline-api-top-p" type="number" min="0" max="1" step="0.01" value="${escapeHtml(o.customApi.top_p ?? "")}" style="width:100%;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.15);border-radius:6px;color:#e8ddd4;padding:5px 8px;font-size:12px;"></label>\n              <label>频率惩罚<input id="outline-api-freq-pen" type="number" min="-2" max="2" step="0.01" value="${escapeHtml(o.customApi.frequency_penalty ?? "")}" style="width:100%;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.15);border-radius:6px;color:#e8ddd4;padding:5px 8px;font-size:12px;"></label>\n              <label>存在惩罚<input id="outline-api-pres-pen" type="number" min="-2" max="2" step="0.01" value="${escapeHtml(o.customApi.presence_penalty ?? "")}" style="width:100%;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.15);border-radius:6px;color:#e8ddd4;padding:5px 8px;font-size:12px;"></label>\n            </div>\n          </details>\n          ${ssRenderJsonFormatControls("outline", o.customApi.extraBodyParamsYaml)}\n          ${ssRenderExtraParamsPanelHtml("outline", { extraBodyParamsYaml: o.customApi.extraBodyParamsYaml, excludeBodyParamsYaml: o.customApi.excludeBodyParamsYaml, extraHeadersYaml: o.customApi.extraHeadersYaml })}\n          <div style="display:flex;gap:6px;margin-top:8px;flex-wrap:wrap;align-items:center;">\n            <select id="outline-saved-api-select" style="flex:1;min-width:160px;">${ssGetCustomApiPresetOptionsHtml()}</select>\n            <button id="outline-saved-api-apply" class="ol-vbtn ol-vbtn-primary">填入</button>\n            <button id="outline-saved-api-save" class="ol-vbtn ol-vbtn-ghost">保存</button>\n            <button id="outline-saved-api-delete" class="ol-vbtn ol-vbtn-danger">删除</button>\n          </div>\n        </div>\n      </div>\n    </section>\n    <section class="ol-tab-pane" data-olpane="adv">\n      <div class="m-head"><span class="mico">🔄</span><h2>动态修正 · 标签过滤</h2></div>\n      <div class="ol-vcard">\n        <div class="ol-vcard-header"><h3>📈🔬 动态分析</h3></div>\n        <div style="display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin-bottom:10px;">\n          <label style="display:flex;align-items:center;gap:6px;font-size:12px;color:#a09088;cursor:pointer;">\n            <input type="checkbox" id="outline-auto-toggle" ${S.outlineAutoAnalysis ? "checked" : ""}> 每隔\n          </label>\n          <input type="number" id="outline-auto-interval" value="${S.outlineAutoInterval}" min="1" style="width:60px;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.2);border-radius:6px;color:#e8ddd4;padding:4px 6px;font-size:12px;">\n          <span style="font-size:12px;color:#a09088;">楼自动修正大纲</span>\n        </div>\n        ${xhSendAnalyzeBtnHtml("outline-send-analyze", S.outlineSendAnalyze === true)}\n        <label class="ol-switch-r