h:34px;height:34px;border-radius:10px;border:1px solid rgba(255,255,255,.1);background:rgba(255,255,255,.04);color:#8a7f78;cursor:pointer;font-size:15px;display:flex;align-items:center;justify-content:center;flex-shrink:0">‹</button>\n        <div style="flex:1;min-width:0"><div style="font-size:15px;font-weight:700;color:#e8ddd4">⚖️ 狐裁</div><div id="fj-mb-sub" style="font-size:10px;color:#706058;margin-top:1px">主控 · 总开关 · 强度</div></div>\n      </div>\n      \x3c!-- PC顶栏 --\x3e\n      <div class="fj-pc-head" style="flex-shrink:0;display:flex;align-items:center;gap:12px;padding:13px 20px;border-bottom:1px solid rgba(255,255,255,.07);background:rgba(0,0,0,.22);position:relative;z-index:2">\n        <div style="font-size:13px;color:#8a7f78">🦊 模块中心 <span style="color:#f0a070;margin:0 6px">▸</span> <span style="color:#e8ddd4;font-size:15px;font-weight:700">⚖️ 狐裁 · 思维链</span></div>\n        <div style="margin-left:auto;display:flex;align-items:center;gap:8px" id="foxjudge-hd-right">\n        </div>\n        <button id="foxjudge-close" style="border:1px solid rgba(255,255,255,.14);background:rgba(255,255,255,.05);color:#8a7f78;border-radius:8px;width:28px;height:28px;cursor:pointer;font-size:13px;transition:all .25s;flex-shrink:0">✕</button>\n      </div>\n      <div class="fj-work">\n        <aside class="fj-rail">\n          <div class="fj-rail-title">🧭 裁决分区</div>\n          <div class="fj-mitem fj-cur" data-tab="main">\n            <span class="fj-mico">⚖️</span>\n            <div class="fj-mtext"><b>主控制台</b><small>总开关 · 强度 · 快捷</small></div>\n          </div>\n          ${t.nativeThinking ? `\n          <div class="fj-mitem" data-tab="native">\n            <span class="fj-mico">🧩</span>\n            <div class="fj-mtext"><b>思维链配置</b><small>原生思维链模块编排</small></div>\n          </div>` : `\n          <div class="fj-mitem" data-tab="phase1">\n            <span class="fj-mico">📜</span>\n            <div class="fj-mtext"><b>一阶段·规则</b><small>固定审查 Prompt</small></div>\n          </div>\n          <div class="fj-mitem" data-tab="phase2">\n            <span class="fj-mico">🧩</span>\n            <div class="fj-mtext"><b>二阶段·模块</b><small>思维链编排</small></div>\n          </div>`}\n          <div class="fj-rail-sec">🛠 配置</div>\n          <div class="fj-mitem" data-tab="api">\n            <span class="fj-mico">🌐</span>\n            <div class="fj-mtext"><b>API 配置</b><small>模型 · 参数 · 预设</small></div>\n          </div>\n          <div class="fj-mitem" data-tab="set">\n            <span class="fj-mico">🔧</span>\n            <div class="fj-mtext"><b>设置</b><small>过滤 · 缓存 · 重试</small></div>\n          </div>\n        </aside>\n        <main class="fj-main">\n          <section class="fj-pane fj-active" data-pane="main">\n      <div style="background:rgba(236, 228, 224, 0.06);border:1px solid rgba(232,120,74,0.15);border-radius:10px;padding:10px 12px;font-size:12px;color:#f0a070;line-height:1.8;">\n         <strong>第一阶段</strong>：检查抢话、人称、文风等预设固定规则……跑完一次就不用管咯……<br>\n         <strong>第二阶段</strong>：每轮都跑，推演当下剧情的角色内心或规划和剧情走向<br>\n         <strong>输出格式</strong>：用 <code>&lt;think_fox~&gt;</code> 包裹，AI只负责思考\n      </div>\n\n      <div style="background:rgba(232,120,74,0.045);border:1px solid rgba(232,120,74,0.18);border-radius:12px;padding:14px;display:flex;flex-direction:column;gap:10px;">\n        <div style="font-weight:700;color:#f0a070;font-size:14px;">⚙️ 总开关</div>\n        <label style="display:flex;align-items:center;justify-content:space-between;font-size:12px;color:#ffd8b8;cursor:pointer;padding:10px 12px;border:1px solid rgba(255,170,90,0.45);border-radius:10px;background:linear-gradient(90deg,rgba(232,120,74,0.16),rgba(255,255,255,0.025));">\n           <span>\n             <strong style="color:#ffb06a;">🧠 使用原生思维链</strong>\n             <span style="display:block;font-size:11px;color:#f0a070;margin-top:4px;line-height:1.5;">\n                开启后，请打开模型原生思维链\n             </span>\n           </span>\n          <input id="foxjudge-native-enabled" type="checkbox" ${t.nativeThinking ? "checked" : ""} style="cursor:pointer;width:18px;height:18px;">\n        </label>\n        <label style="display:flex;align-items:center;justify-content:space-between;font-size:12px;color:#ffd8b8;cursor:pointer;padding:10px 12px;border:1px solid rgba(255,170,90,0.45);border-radius:10px;background:linear-gradient(90deg,rgba(232,120,74,0.16),rgba(255,255,255,0.025));">\n           <span>\n             <strong style="color:#ffb06a;">🦊 启用内置思维链</strong>\n             <span style="display:block;font-size:11px;color:#f0a070;margin-top:4px;line-height:1.5;">\n               开启后，AI 回复前会先经过两阶段思考，思考结果注入提示词并写入主模型输出楼层顶部，正文AI就只负责写正文啦……\n             </span>\n           </span>\n          <input id="foxjudge-enabled" type="checkbox" ${t.enabled && !t.nativeThinking ? "checked" : ""} style="cursor:pointer;width:18px;height:18px;">\n        </label>\n        <div id="foxjudge-context-floors-row" style="display:flex;align-items:center;gap:10px;font-size:12px;color:#a09088;padding:10px 12px;border:1px solid rgba(232,120,74,0.18);border-radius:10px;background:rgba(255,255,255,0.025);flex-wrap:wrap;">\n          <span style="flex:0 0 auto;color:#ffd8b8;">📊 分析楼层限制：</span>\n          <input id="foxjudge-context-floors" type="number" value="${t.contextFloors ?? 10}" min="0" max="9999" style="width:80px;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.2);border-radius:6px;color:#e8ddd4;padding:4px 6px;font-size:12px;">\n          <span style="flex:1 1 100%;font-size:11px;color:#706058;line-height:1.5;">0=发送完整聊天上下文；N=按实际聊天楼层只发送最新 N 楼（严格生效）。</span>\n        </div>\n      </div>\n\n       <div style="background:rgba(232,120,74,0.025);border:1px solid rgba(232,120,74,0.1);border-radius:12px;padding:14px;display:flex;flex-direction:column;gap:10px;">\n        <div style="font-weight:700;color:#f0a070;font-size:14px;">📡 流式传输</div>\n        <label style="display:flex;align-items:center;justify-content:space-between;font-size:12px;color:#ffd8b8;curso