        return `<button type="button" data-strength="${e}" style="padding:9px 6px;border:1px solid ${o ? "rgba(255,170,90,0.55)" : "rgba(232,120,74,0.2)"};border-radius:8px;background:${o ? "rgba(232,120,74,0.22)" : "rgba(255,255,255,0.03)"};color:${o ? "#ffb06a" : "#a09088"};cursor:pointer;font-size:12px;font-weight:600;">${n[e]}</button>`;
      })
      .join(
        "",
      )}\n        </div>\n      </div>\n      </section>\n\n      ${t.nativeThinking ? `<section class="fj-pane" data-pane="native">\n      <div style="background:rgba(232,120,74,0.025);border:1px solid rgba(232,120,74,0.1);border-radius:12px;padding:14px;display:flex;flex-direction:column;gap:10px;">\n        <div style="display:flex;justify-content:space-between;align-items:center;">\n          <div style="font-weight:700;color:#f0a070;font-size:14px;">🧠 原生思维链配置</div>\n          <button type="button" id="foxjudge-phase2-reset" style="padding:5px 10px;border:1px solid rgba(139,0,0,0.3);border-radius:6px;background:rgba(139,0,0,0.13);color:#d08080;cursor:pointer;font-size:11px;">↩️ 恢复默认</button>\n        </div>\n        <div style="font-size:11px;color:#a09088;line-height:1.55;">\n          与内置思维链（二阶段）共用同一套模块与排序：在这里调整后两边同步生效。<br>\n          开启原生思维链后，模块会按顺序注入预设条目「🦊狐裁原生思维链注入」（think1 变量），由主模型在生成正文前按流程自行思考，无需额外解析 API。<br>\n          头部/尾部为原生思维链专用提示词：不要求输出任何标签或格式，只引导主模型按流程思考后直接输出正文。修改模块后会自动重新注入；也可点下方按钮手动立即注入。\n        </div>\n        <div style="display:flex;gap:8px;flex-wrap:wrap;">\n          <button type="button" id="foxjudge-think-preset-os" style="padding:8px 12px;border:1px solid rgba(232,120,74,0.3);border-radius:8px;background:rgba(232,120,74,0.12);color:#f0a070;cursor:pointer;font-size:12px;font-weight:600;">🎭 排序成 OS 思维链</button>\n          <button type="button" id="foxjudge-think-preset-director" style="padding:8px 12px;border:1px solid rgba(232,120,74,0.3);border-radius:8px;background:rgba(232,120,74,0.12);color:#f0a070;cursor:pointer;font-size:12px;font-weight:600;">🎬 排序成导演思维链</button>\n          <button type="button" id="foxjudge-think-add" style="padding:8px 12px;border:1px solid rgba(232,120,74,0.2);border-radius:8px;background:rgba(255,255,255,0.03);color:#a09088;cursor:pointer;font-size:12px;">➕ 新增自定义模块</button>\n          <button type="button" id="foxjudge-native-apply-now" style="padding:8px 12px;border:1px solid rgba(255,170,90,0.45);border-radius:8px;background:rgba(232,120,74,0.16);color:#ffb06a;cursor:pointer;font-size:12px;font-weight:600;">🌕 立即注入到预设条目</button>\n        </div>\n        <div id="foxjudge-think-grid" style="display:grid;grid-template-columns:1fr 1.3fr;gap:10px;">\n          <div style="display:flex;flex-direction:column;gap:4px;">\n            <div style="font-size:11px;color:#706058;">未启用模块（拖到右侧启用，或点 ⇢）</div>\n            <div id="foxjudge-think-pool" style="min-height:200px;background:rgba(0,0,0,0.18);border:1px dashed rgba(232,120,74,0.18);border-radius:8px;padding:8px;display:flex;flex-direction:column;gap:6px;"></div>\n          </div>\n          <div style="display:flex;flex-direction:column;gap:4px;">\n            <div style="font-size:11px;color:#706058;">启用排序区（从上到下 = 拼接顺序，拖动或用 ↑↓ 排序）</div>\n            <div id="foxjudge-think-active" style="min-height:200px;background:rgba(232,120,74,0.06);border:1px dashed rgba(232,120,74,0.25);border-radius:8px;padding:8px;display:flex;flex-direction:column;gap:6px;"></div>\n          </div>\n        </div>\n      </div>\n      </section>` : `<section class="fj-pane" data-pane="phase1">\n      <div style="background:rgba(232,120,74,0.025);border:1px solid rgba(232,120,74,0.1);border-radius:12px;padding:14px;display:flex;flex-direction:column;gap:10px;">\n        <div style="display:flex;justify-content:space-between;align-items:center;">\n          <div style="font-weight:700;color:#f0a070;font-size:14px;">📜 第一阶段：规则审查</div>\n          <button type="button" id="foxjudge-phase1-reset" style="padding:5px 10px;border:1px solid rgba(139,0,0,0.3);border-radius:6px;background:rgba(139,0,0,0.13);color:#d08080;cursor:pointer;font-size:11px;">↩️ 恢复默认</button>\n        </div>\n        <div style="font-size:11px;color:#a09088;line-height:1.55;">\n          同角色卡只跑一次，换卡或改预设条目后自动重跑\n        </div>\n        <textarea id="foxjudge-phase1-prompt" style="width:100%;min-height:220px;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.2);border-radius:8px;color:#e8ddd4;padding:10px;font-size:12px;font-family:monospace;resize:vertical;box-sizing:border-box;white-space:pre-wrap;">${escapeHtml(t.phase1Prompt)}</textarea>\n        <details style="border:1px solid rgba(232,120,74,0.14);border-radius:8px;background:rgba(255,255,255,0.02);">\n          <summary style="cursor:pointer;padding:8px 10px;color:#f0a070;font-size:12px;font-weight:600;user-select:none;">🏷️ 一阶段标签过滤</summary>\n          <div style="padding:10px;">\n            <div style="font-size:11px;color:#90756a;line-height:1.6;margin-bottom:8px;">\n              仅作用于第一阶段（规则审查）的上下文。默认额外排除 <code>&lt;content&gt;&lt;/content&gt;</code>——第一阶段不需要正文。<br>\n              点击左侧"▸"可展开/收起；修改后点下方保存按钮生效。\n            </div>\n            <label style="display:flex;align-items:center;gap:6px;font-size:12px;color:#a09088;cursor:pointer;margin-bottom:8px;">\n              <input type="checkbox" id="foxjudge-phase1-filter-enabled" ${(t.phase1FilterSettings || Fn).enableContentFilter !== false ? "checked" : ""}>\n              启用一阶段标签过滤\n            </label>\n            ${ssCreateTagPairsEditorHtml("foxjudge-phase1-inc", "✅ 包含标签：只保留这些标签范围内的内容", (t.phase1FilterSettings || Fn).includeTagPairs, "一行是一组。左边开始标签，右边结束标签。")}\n            ${ssCreateTagPairsEditorHtml("foxjudge-phase1-exc", "❌ 排除标签：删除这些标签范围内的内容", (t.phase1FilterSettings || Fn).excludeTagPairs, "功能与包含标签相反。允许只填结束标签。")}\n            <button type="button" id="foxjudge-phase1-filter-save" style="width:100%;padding:8px 12px;border:1px solid rgba(232,120,74,0.3);border-radius:8px;background:rgba(232,120,74,0.1);color:#f0a070;cursor:pointer;font-size:12px;">💾 保存一阶段过滤设置</button>\n          </div>\n        </details>\n      </div>\n      </section>\n\n      <section class="fj-pane" data-pane="phase2">\n      <div style="background:rgba(232,120,74,0.025);border:1px solid rgba(232,120,74,0.1);border-radius:12px;padding:14px;display:flex;flex-direction:column;gap:10px;">\n        <div style="display:flex;justify-content:space-between;align-items:center;">\n          <div style="font-weight:700;color:#f0a070;font-size:14px;">🎬 第二阶段：动态思考</div>\n          <button type="button" id="foxjudge-phase2-reset" style="padding:5px 10px;border:1px solid rgba(139,0,0,0.3);border-radius:6px;background:rgba(139,0,0,0.13);color:#d08080;cursor:pointer;font-size:11px;">↩️ 恢复默认</button>\n        </div>\n        <div style="font-size:11px;color:#a09088;line-height:1.55;">\n          思维链由多个模块拼接而成，左侧是未启用模块池，右侧是启用排序区、点击 ✏️ 编辑。\n        </div>\n        <div style="display:flex;gap:8px;flex-wrap:wrap;">\n          <button type="button" id="foxjudge-think-preset-os" style="padding:8px 12px;border:1px solid rgba(232,120,74,0.3);border-radius:8px;background:rgba(232,120,74,0.12);color:#f0a070;cursor:pointer;font-size:12px;font-weight:600;">🎭 排序成 OS 思维链</button>\n          <button type="button" id="foxjudge-think-preset-director" style="padding:8px 12px;border:1px solid rgba(232,120,74,0.3);border-radius:8px;background:rgba(232,120,74,0.12);color:#f0a070;cursor:pointer;font-size:12px;font-weight:600;">🎬 排序成导演思维链</button>\n          <button type="button" id="foxjudge-think-add" style="padding:8px 12px;border:1px solid rgba(232,120,74,0.2);border-radius:8px;background:rgba(255,255,255,0.03);color:#a09088;cursor:pointer;font-size:12px;">➕ 新增自定义模块</button>\n        </div>\n        <div id="foxjudge-think-grid" style="display:grid;grid-template-columns:1fr 1.3fr;gap:10px;">\n          <div style="display:flex;flex-direction:column;gap:4px;">\n            <div style="font-size:11px;color:#706058;">未启用模块（拖到右侧启用，或点 ⇢）</div>\n            <div id="foxjudge-think-pool" style="min-height:200px;background:rgba(0,0,0,0.18);border:1px dashed rgba(232,120,74,0.18);border-radius:8px;padding:8px;display:flex;flex-direction:column;gap:6px;"></div>\n          </div>\n          <div style="display:flex;flex-direction:column;gap:4px;">\n            <div style="font-size:11px;color:#706058;">启用排序区（从上到下 = 拼接顺序，拖动或用 ↑↓ 排序）</div>\n            <div id="foxjudge-think-active" style="min-height:200px;background:rgba(232,120,74,0.06);border:1px dashed rgba(232,120,74,0.25);border-radius:8px;padding:8px;display:flex;flex-direction:column;gap:6px;"></div>\n          </div>\n        </div>\n        <details style="border:1px solid rgba(232,120,74,0.14);border-radius:8px;background:rgba(255,255,255,0.02);">\n          <summary style="cursor:pointer;padding:8px 10px;color:#f0a070;font-size:12px;font-weight:600;user-select:none;">🏷️ 二阶段标签过滤</summary>\n          <div style="padding:10px;">\n            <div style="font-size:11px;color:#90756a;line-height:1.6;margin-bottom:8px;">\n              仅作用于第二阶段（动态思考）的上下文。默认沿用原统一过滤配置（不含 <code>&lt;content&gt;</code> 排除）。<br>\n              点击左侧"▸"可展开/收起；修改后点下方保存按钮生效。\n            </div>\n            <label style="display:flex;align-items:center;gap:6px;font-size:12px;color:#a09088;cursor:pointer;margin-bottom:8px;">\n              <input type="checkbox" id="foxjudge-phase2-filter-enabled" ${(t.phase2FilterSettings || Fn).enableContentFilter !== false ? "checked" : ""}>\n              启用二阶段标签过滤\n            </label>\n            ${ssCreateTagPairsEditorHtml("foxjudge-phase2-inc", "✅ 包含标签：只保留这些标签范围内的内容", (t.phase2FilterSettings || Fn).includeTagPairs, "一行是一组。左边开始标签，右边结束标签。")}\n            ${ssCreateTagPairsEditorHtml("foxjudge-phase2-exc", "❌ 排除标签：删除这些标签范围内的内容", (t.phase2FilterSettings || Fn).excludeTagPairs, "功能与包含标签相反。允许只填结束标签。")}\n            <button type="button" id="foxjudge-phase2-filter-save" style="width:100%;padding:8px 12px;border:1px solid rgba(232,120,74,0.3);border-radius:8px;background:rgba(232,120,74,0.1);color:#f0a070;cursor:pointer;font-size:12px;">💾 保存二阶段过滤设置</button>\n          </div>\n        </details>\n      </div>\n      </section>`}\n\n      <section class="fj-pane" data-pane="api">\n      <div class="fj-pane-h"><span class="fj-mico" style="width:32px;height:32px;border-radius:9px;font-size:15px">🌐</span><h2>API 配置 · 模型与参数</h2></div>\n      <div style="background:rgba(232,120,74,0.025);border:1px solid rgba(232,120,74,0.1);border-radius:12px;padding:14px;display:flex;flex-direction:column;gap:10px;">\n        <div style="font-weight:700;color:#f0a070;font-size:14px;">🤖 分析 API 配置</div>\n        <div style="font-size:11px;color:#a09088;line-height:1.55;">\n          \n        </div>\n        <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px 12px;">\n          <div>\n            <label style="font-size:11px;color:#706058;">API 来源</label>\n            <select id="foxjudge-api-type" style="width:100%;box-sizing:border-box;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.15);border-radius:6px;color:#e8ddd4;padding:5px 8px;font-size:12px;">\n              <option value="current" ${t.apiType === "current" ? "selected" : ""}>酒馆当前 API</option>\n              <option value="custom" ${t.apiType === "custom" ? "selected" : ""}>自定义 OpenAI 兼容 API</option>\n            </select>\n          </div>\n        </div>\n\n        <div id="foxjudge-custom-api-section" style="display:${t.apiType === "custom" ? "block" : "none"};margin-top:10px;">\n          <div id="foxjudge-direct-section" style="display:block;">\n            <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px 12px;">\n              <div>\n                <label style="font-size:11px;color:#706058;">API 地址</label>\n                <input id="foxjudge-api-url" type="text" value="${escapeHtml(t.customApi.apiurl || "")}" style="width:100%;box-sizing:border-box;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.15);border-radius:6px;color:#e8ddd4;padding:5px 8px;font-size:12px;">\n              </div>\n              <div>\n                <label style="font-size:11px;color:#706058;">API Key</label>\n                <input id="foxjudge-api-key" type="password" value="${escapeHtml(t.customApi.key || "")}" style="width:100%;box-sizing:border-box;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.15);border-radius:6px;color:#e8ddd4;padding:5px 8px;font-size:12px;">\n              </div>\n            </div>\n          </div>\n\n          <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px 12px;margin-top:8px;">\n            <div>\n              <label style="font-size:11px;color:#706058;">模型</label>\n              <div style="display:flex;gap:6px;">\n                <input id="foxjudge-api-model" type="text" value="${escapeHtml(t.customApi.model || "")}" style="flex:1;box-sizing:border-box;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.15);border-radius:6px;color:#e8ddd4;padding:5px 8px;font-size:12px;">\n                <button id="foxjudge-fetch-models" style="padding:5px 10px;border:1px solid rgba(232,120,74,0.2);border-radius:6px;background:rgba(255,255,255,0.03);color:#a09088;cursor:pointer;font-size:11px;white-space:nowrap;">获取模型</button>\n              </div>\n            </div>\n            <div>\n              <label style="font-size:11px;color:#706058;">模型列表</label>\n              <select id="foxjudge-api-model-select" style="width:100%;box-sizing:border-box;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.15);border-radius:6px;color:#e8ddd4;padding:5px 8px;font-size:12px;"><option value="">（从列表选择）</option></select>\n            </div>\n          </div>\n\n          <details style="margin-top:10px;border:1px solid rgba(232,120,74,0.12);border-radius:8px;background:rgba(255,255,255,0.02);">\n            <summary style="cursor:pointer;padding:8px 10px;color:#f0a070;font-size:12px;font-weight:600;user-select:none;">⚙️ 高级参数</summary>\n            <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px 12px;padding:10px;">\n              <div><label style="font-size:11px;color:#706058;">温度</label><input id="foxjudge-api-temp" type="number" min="0" max="2" step="0.1" value="${escapeHtml(t.customApi.temperature ?? "")}" style="width:100%;box-sizing:border-box;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.15);border-radius:6px;color:#e8ddd4;padding:5px 8px;font-size:12px;"></div>\n              <div><label style="font-size:11px;color:#706058;">最大 token</label><input id="foxjudge-api-max-tokens" type="number" min="0" step="128" value="${escapeHtml(t.customApi.max_tokens ?? "")}" style="width:100%;box-sizing:border-box;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.15);border-radius:6px;color:#e8ddd4;padding:5px 8px;font-size:12px;"></div>\n              <div><label style="font-size:11px;color:#706058;">Top P</label><input id="foxjudge-api-top-p" type="number" min="0" max="1" step="0.01" value="${escapeHtml(t.customApi.top_p ?? "")}" style="width:100%;box-sizing:border-box;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.15);border-radius:6px;color:#e8ddd4;padding:5px 8px;font-size:12px;"></div>\n              <div><label style="font-size:11px;color:#706058;">频率惩罚</label><input id="foxjudge-api-freq-pen" type="number" min="-2" max="2" step="0.01" value="${escapeHtml(t.customApi.frequency_penalty ?? "")}" style="width:100%;box-sizing:border-box;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.15);border-radius:6px;color:#e8ddd4;padding:5px 8px;font-size:12px;"></div>\n              <div><label style="font-size:11px;color:#706058;">存在惩罚</label><input id="foxjudge-api-pres-pen" type="number" min="-2" max="2" step="0.01" value="${escapeHtml(t.customApi.presence_penalty ?? "")}" style="width:100%;box-sizing:border-box;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.15);border-radius:6px;color:#e8ddd4;padding:5px 8px;font-size:12px;"></div>\n            </div>\n          </details>\n          ${ssRenderJsonFormatControls("foxjudge", t.customApi.extraBodyParamsYaml, { onlyThinking: true })}\n          ${ssRenderExtraParamsPanelHtml("foxjudge", { extraBodyParamsYaml: t.customApi.extraBodyParamsYaml, excludeBodyParamsYaml: t.customApi.excludeBodyParamsYaml, extraHeadersYaml: t.customApi.extraHeadersYaml })}\n          <div style="display:flex;gap:6px;margin-top:8px;flex-wrap:wrap;align-items:center;">\n            <select id="foxjudge-saved-api-select" style="flex:1;min-width:160px;box-sizing:border-box;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.15);border-radius:6px;color:#e8ddd4;padding:5px 8px;font-size:12px;">${ssGetCustomApiPresetOptionsHtml()}</select>\n            <button id="foxjudge-saved-api-apply" style="padding:5px 10px;border:1px solid rgba(232,120,74,0.25);border-radius:6px;background:rgba(232,120,74,0.08);color:#f0a070;cursor:pointer;font-size:11px;">填入</button>\n            <button id="foxjudge-saved-api-save" style="padding:5px 10px;border:1px solid rgba(232,120,74,0.25);border-radius:6px;background:rgba(255,255,255,0.03);color:#a09088;cursor:pointer;font-size:11px;">保存</button>\n            <button id="foxjudge-saved-api-delete" style="padding:5px 10px;border:1px solid rgba(139,0,0,0.3);border-radius:6px;background:rgba(139,0,0,0.12);color:#d08080;cursor:pointer;font-size:11px;">删除</button>\n          </div>\n        </div>\n      </div>\n      </section>\n\n      <section class="fj-pane" data-pane="set">\n      <div class="fj-pane-h"><span class="fj-mico" style="width:32px;height:32px;border-radius:9px;font-size:15px">🔧</span><h2>设置 · 过滤 · 缓存 · 重试</h2></div>\n\n      <div style="background:rgba(232,120,74,0.025);border:1px solid rgba(232,120,74,0.1);border-radius:12px;padding:14px;display:flex;flex-direction:column;gap:10px;">\n        <details>\n          <summary style="cursor:pointer;font-weight:700;color:#f0a070;font-size:14px;user-select:none;">🏷️ 上下文标签过滤</summary>\n          <div style="font-size:11px;color:#90756a;line-height:1.6;margin:8px 0;">\n            🆕 标签过滤已拆分为<strong>一阶段</strong>与<strong>二阶段</strong>两套独立配置：<br>\n            · 📜 一阶段（规则审查）过滤 → 请到「<b>一阶段·规则</b>」页，在自定义一阶段提示词下方展开「🏷️ 一阶段标签过滤」配置（默认额外排除 <code>&lt;content&gt;&lt;/content&gt;</code>，第一阶段不需要正文）；<br>\n            · 🎬 二阶段（动态思考）过滤 → 请到「<b>二阶段·模块</b>」页，在思维链模块排序区下方展开「🏷️ 二阶段标签过滤」配置（默认沿用原统一过滤）。<br>\n            两套配置独立保存、互不影响。\n          </div>\n        </details>\n      </div>\n\n      <div style="background:rgba(232,120,74,0.025);border:1px solid rgba(232,120,74,0.1);border-radius:12px;padding:14px;display:flex;flex-direction:column;gap:10px;">\n        <div style="font-weight:700;color:#f0a070;font-size:14px;">💾 缓存与重跑</div>\n        <div style="font-size:11px;color:#a09088;line-height:1.55;">\n          第一阶段结果按角色卡缓存，换卡或改预设自动失效\n        </div>\n        <label style="display:flex;align-items:center;justify-content:space-between;font-size:12px;color:#ffd8b8;cursor:pointer;padding:8px 12px;border:1px solid rgba(232,120,74,0.15);border-radius:8px;background:rgba(255,255,255,0.02);">\n          <span>\n            <strong style="color:#f0a070;">💾 启用第一阶段缓存</strong>\n            <span style="display:block;font-size:11px;color:#a09088;margin-top:2px;">关闭后第一阶段每次都重新思考</span>\n          </span>\n          <input id="foxjudge-cache-enabled" type="checkbox" ${t.cacheEnabled ? "checked" : ""} style="cursor:pointer;width:18px;height:18px;">\n        </label>\n        <label style="display:flex;align-items:center;justify-content:space-between;font-size:12px;color:#ffd8b8;cursor:pointer;padding:8px 12px;border:1px solid rgba(232,120,74,0.15);border-radius:8px;background:rgba(255,255,255,0.02);">\n          <span>\n            <strong style="color:#f0a070;">📌 固定第一阶段思考</strong>\n            <span style="display:block;font-size:11px;color:#a09088;margin-top:2px;">开启后第一阶段缓存不会因角色卡/预设变化自动失效，会一直使用当前保存内容。</span>\n          </span>\n          <input id="foxjudge-phase1-fixed" type="checkbox" ${t.phase1Fixed ? "checked" : ""} style="cursor:pointer;width:18px;height:18px;">\n        </label>\n        <div style="display:flex;gap:8px;flex-wrap:wrap;">\n          <button type="button" id="foxjudge-clear-cache" style="flex:1;padding:8px 12px;border:1px solid rgba(139,0,0,0.3);border-radius:8px;background:rgba(139,0,0,0.13);color:#d08080;cursor:pointer;font-size:12px;">🧹 清空全部缓存</button>\n          <button type="button" id="foxjudge-force-refresh" style="flex:1;padding:8px 12px;border:1px solid rgba(232,120,74,0.3);border-radius:8px;background:rgba(232,120,74,0.1);color:#f0a070;cursor:pointer;font-size:12px;">🔄 强制重跑第一阶段</button>\n          <button type="button" id="foxjudge-run-phase1-now" style="flex:1;padding:8px 12px;border:1px solid rgba(255,170,90,0.42);border-radius:8px;background:rgba(232,120,74,0.16);color:#ffb06a;cursor:pointer;font-size:12px;font-weight:700;">🧠 立即思考第一阶段</button>\n        </div>\n      </div>\n\n      <div style="background:rgba(232,120,74,0.025);border:1px solid rgba(232,120,74,0.1);border-radius:12px;padding:14px;display:flex;flex-direction:column;gap:10px;">\n        <div style="font-weight:700;color:#f0a070;font-size:14px;">📋 第一阶段缓存内容</div>\n        <div style="font-size:11px;color:#a09088;line-height:1.55;">\n          当前角色卡的第一阶段思考结果。可直接编辑并保存，编辑后下次发送时使用编辑后的内容。\n        </div>\n        <textarea id="foxjudge-phase1-cache-viewer" style="width:100%;min-height:150px;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.2);border-radius:8px;color:#e8ddd4;padding:10px;font-size:12px;font-family:monospace;resize:vertical;box-sizing:border-box;white-space:pre-wrap;">${(() => {
      try {
        const e = foxJudgeGetStaticCache(getCurrentCharId());
        return escapeHtml(e?.phase1_result || "（无缓存，下次发送时自动生成）");
      } catch {
        return "（读取失败）";
      }
    })()}</textarea>\n        <div style="display:flex;gap:8px;flex-wrap:wrap;">\n          <button type="button" id="foxjudge-phase1-cache-save" style="flex:1;padding:8px 12px;border:1px solid rgba(232,120,74,0.3);border-radius:8px;background:rgba(232,120,74,0.1);color:#f0a070;cursor:pointer;font-size:12px;">💾 保存编辑</button>\n          <button type="button" id="foxjudge-phase1-cache-refresh" style="flex:1;padding:8px 12px;border:1px solid rgba(232,120,74,0.3);border-radius:8px;background:rgba(232,120,74,0.1);color:#f0a070;cursor:pointer;font-size:12px;">🔄 刷新显示</button>\n        </div>\n      </div>\n\n      <div style="background:rgba(232,120,74,0.025);border:1px solid rgba(232,120,74,0.1);border-radius:12px;padding:14px;display:flex;flex-direction:column;gap:10px;">\n        <div style="font-weight:700;color:#f0a070;font-size:14px;">🔁 Swipe / Reroll 重新思考</div>\n        <div style="font-size:11px;color:#a09088;line-height:1.55;">\n           默认开启。开启时：swipe / reroll 会先拦截按钮、重跑第二阶段思维链，再释放按钮触发生成。<br>\n           关闭时：swipe / reroll 不再重跑思维链，而是<strong>沿用上一次已经思考完的完整思维链</strong>注入到新输出楼层顶部，保持一二阶段不变（适合：你已经满意当前思考，只想换一个正文版本）。\n        </div>\n        <label style="display:flex;align-items:center;justify-content:space-between;font-size:12px;color:#ffd8b8;cursor:pointer;padding:8px 12px;border:1px solid rgba(232,120,74,0.15);border-radius:8px;background:rgba(255,255,255,0.02);">\n          <span>\n            <strong style="color:#f0a070;">🔁 Swipe 时重新思考</strong>\n            <span style="display:block;font-size:11px;color:#a09088;margin-top:2px;">默认开启。开启=重跑第二阶段并注入新思维链；关闭=沿用上一次完整思维链直接注入。</span>\n          </span>\n          <input id="foxjudge-swipe-rethink" type="checkbox" ${t.swipeRethink ? "checked" : ""} style="cursor:pointer;width:18px;height:18px;">\n        </label>\n        <label style="display:flex;align-items:center;justify-content:space-between;font-size:12px;color:#ffd8b8;cursor:pointer;padding:8px 12px;border:1px solid rgba(232,120,74,0.15);border-radius:8px;background:rgba(255,255,255,0.02);">\n          <span>\n            <strong style="color:#f0a070;">🔁 Reroll 时重新思考</strong>\n            <span style="display:block;font-size:11px;color:#a09088;margin-top:2px;">默认开启。开启=重跑第二阶段并注入新思维链；关闭=沿用上一次完整思维链直接注入。</span>\n          </span>\n          <input id="foxjudge-reroll-rethink" type="checkbox" ${t.rerollRethink ? "checked" : ""} style="cursor:pointer;width:18px;height:18px;">\n        </label>\n      </div>\n\n      <div style="background:rgba(232,120,74,0.025);border:1px solid rgba(232,120,74,0.1);border-radius:12px;padding:14px;display:flex;flex-direction:column;gap:10px;">\n        <div style="font-weight:700;color:#f0a070;font-size:14px;">🔄 空回复/报错重试</div>\n        <div style="font-size:11px;color:#a09088;line-height:1.55;">\n           当思维链阶段返回空内容、报错、被拒答或结构残缺时自动重试。0=不重试（一报错就空思维链），1~5=重试次数。\n        </div>\n        <label style="display:flex;align-items:center;justify-content:space-between;font-size:12px;color:#ffd8b8;cursor:pointer;padding:8px 12px;border:1px solid rgba(232,120,74,0.15);border-radius:8px;background:rgba(255,255,255,0.02);">\n          <span>\n            <strong style="color:#f0a070;">🔘 启用空回复/报错重试</strong>\n            <span style="display:block;font-size:11px;color:#a09088;margin-top:2px;">默认关闭。关闭后思维链只跑一次，不检测空回/报错，直接使用结果。</span>\n          </span>\n          <input id="foxjudge-retry-enabled" type="checkbox" ${t.retryEnabled ? "checked" : ""} style="width:18px;height:18px;cursor:pointer;accent-color:#f0a070;">\n        </label>\n        <label style="display:flex;align-items:center;justify-content:space-between;font-size:12px;color:#ffd8b8;cursor:pointer;padding:8px 12px;border:1px solid rgba(232,120,74,0.15);border-radius:8px;background:rgba(255,255,255,0.02);">\n          <span>\n            <strong style="color:#f0a070;">🔄 最大重试次数</strong>\n            <span style="display:block;font-size:11px;color:#a09088;margin-top:2px;">思维链空回复/拒答/结构残缺时自动重试（推荐 3 次）；仅在上方开关开启时生效</span>\n          </span>\n          <input id="foxjudge-max-retries" type="number" min="0" max="5" value="${t.maxRetries ?? 3}" style="width:50px;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.2);border-radius:6px;color:#e8ddd4;padding:5px 8px;font-size:12px;text-align:center;">\n        </label>\n        <label style="display:flex;align-items:center;justify-content:space-between;font-size:12px;color:#ffd8b8;cursor:pointer;padding:8px 12px;border:1px solid rgba(232,120,74,0.15);border-radius:8px;background:rgba(255,255,255,0.02);">\n          <span>\n            <strong style="color:#f0a070;">🛑 第二阶段失败即停止</strong>\n            <span style="display:block;font-size:11px;color:#a09088;margin-top:2px;">开启后狐裁第二阶段失败时不请求正文，直接提示你手动重roll或swipe（默认关闭 = 沿用旧兜底：仅注入第一阶段并照常生成）</span>\n          </span>\n          <input id="foxjudge-stop-on-phase2-fail" type="checkbox" ${t.stopOnPhase2Fail ? "checked" : ""} style="width:18px;height:18px;cursor:pointer;accent-color:#f0a070;">\n        </label>\n      </div>\n\n      <div style="background:rgba(232,120,74,0.025);border:1px solid rgba(232,120,74,0.1);border-radius:12px;padding:14px;display:flex;flex-direction:column;gap:10px;">\n        <div style="font-weight:700;color:#f0a070;font-size:14px;">📐 面板大小 · UI 适配渲染</div>\n        <div style="font-size:11px;color:#a09088;line-height:1.55;">\n          自定义狐裁面板的宽高，改完立即生效并记住。窄面板会自动压缩侧栏、两栏模块区自动合并为单栏，适配你的屏幕与排版习惯。\n        </div>\n        <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px;">\n          <button type="button" id="foxjudge-size-preset-c" style="padding:9px 6px;border:1px solid rgba(232,120,74,0.2);border-radius:8px;background:rgba(255,255,255,0.03);color:#a09088;cursor:pointer;font-size:12px;font-weight:600;">🔹 紧凑 720×540</button>\n          <button type="button" id="foxjudge-size-preset-m" style="padding:9px 6px;border:1px solid rgba(255,170,90,0.55);border-radius:8px;background:rgba(232,120,74,0.22);color:#ffb06a;cursor:pointer;font-size:12px;font-weight:600;">🔸 标准 960×700</button>\n          <button type="button" id="foxjudge-size-preset-l" style="padding:9px 6px;border:1px solid rgba(232,120,74,0.2);border-radius:8px;background:rgba(255,255,255,0.03);color:#a09088;cursor:pointer;font-size:12px;font-weight:600;">🔹 宽大 1200×820</button>\n        </div>\n        <div style="display:flex;gap:8px;align-items:flex-end;flex-wrap:wrap;">\n          <div style="display:flex;flex-direction:column;gap:4px;flex:1;min-width:120px;">\n            <label style="font-size:11px;color:#706058;">宽度（px）</label>\n            <input id="foxjudge-size-w" type="number" min="560" max="1920" step="10" value="${t.panelSize?.w ?? 960}" style="width:100%;box-sizing:border-box;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.2);border-radius:6px;color:#e8ddd4;padding:6px 8px;font-size:12px;">\n          </div>\n          <div style="display:flex;flex-direction:column;gap:4px;flex:1;min-width:120px;">\n            <label style="font-size:11px;color:#706058;">高度（px）</label>\n            <input id="foxjudge-size-h" type="number" min="420" max="1200" step="10" value="${t.panelSize?.h ?? 700}" style="width:100%;box-sizing:border-box;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.2);border-radius:6px;color:#e8ddd4;padding:6px 8px;font-size:12px;">\n          </div>\n          <button type="button" id="foxjudge-size-apply" style="flex-shrink:0;padding:9px 16px;border:1px solid rgba(255,170,90,0.5);border-radius:8px;background:rgba(232,120,74,0.18);color:#ffb06a;cursor:pointer;font-size:12px;font-weight:600;">✅ 应用</button>\n        </div>\n        <div style="font-size:11px;color:#706058;line-height:1.5;" id="foxjudge-size-hint">输入数值或点预设，点「应用」立即调整当前面板大小。</div>\n      </div>\n      </section>\n        </main>\n      </div>\n      <nav class="fj-dock">\n        <div class="fj-dock-item fj-cur" data-tab="main"><div class="fj-d-ic">⚖️</div><div class="fj-d-t">主控</div></div>\n        <div class="fj-dock-item" data-tab="phase1"><div class="fj-d-ic">📜</div><div class="fj-d-t">一阶段</div></div>\n        <div class="fj-dock-item" data-tab="phase2"><div class="fj-d-ic">🧩</div><div class="fj-d-t">二阶段</div></div>\n        <div class="fj-dock-item" data-tab="api"><div class="fj-d-ic">🌐</div><div class="fj-d-t">API</div></div>\n        <div class="fj-dock-item" data-tab="set"><div class="fj-d-ic">⚙️</div><div class="fj-d-t">设置</div></div>\n      </nav>\n    `;
    R.body.appendChild(n);
    R.body.appendChild(o);
    xhGuideEnhancePanel(o, "foxjudge", "狐裁");
    try {
      const e = o.querySelector('[data-pane="set"]');
      if (e) {
        xhMountPromptEditor(e, "fox_judge", "狐裁思维链注入标记");
      }
    } catch (e) {
      log("[狐裁] 挂载提示词编辑器失败", e);
    }
    ssAttachAutoSave(o, {
      resolveSaveBtns: (e) => {
        if (!e) return [];
        const t = e.closest?.(
          ".foxjudge-inc-tag-module, .foxjudge-exc-tag-module, " +
            ".foxjudge-inc-tag-row, .foxjudge-exc-tag-row",
        );
        if (t) return ["foxjudge-filter-save"];
        const n = e.id;
        if (!n) return [];
        if (n === "foxjudge-phase1-cache-viewer")
          return ["foxjudge-phase1-cache-save"];
        return [];
      },
    });
    ssAttachPanelResetButton(o, {
      label: "↩ 恢复狐裁默认设置",
      confirm:
        "确定要恢复狐裁本面板的全部设置为默认吗？\n\n这会清掉：第一/二阶段提示词、强度、缓存开关、自定义思考要求、自定义 API、标签过滤和聊天楼层限制等。\n\n角色卡静态缓存会标记失效，避免继续复用旧楼层范围生成的第一阶段思考。\n\n此操作不可撤销。",
      onReset: () => {
        try {
          for (const e of Object.values(kn)) {
            if (e === kn.charCachePrefix) continue;
            try {
              r.removeItem(e);
            } catch {}
          }
          try {
            foxJudgeInvalidateStaticCache({ respectFixed: false });
          } catch {}
          try {
            foxJudgeRestoreNativePreset().catch((e) =>
              log("[狐裁] 重置时还原原生思维链条目失败", e),
            );
          } catch {}
        } finally {
          try {
            _fjTkCloseEditor();
          } catch {}
          R.getElementById("ss-foxjudge-overlay")?.remove();
          o.remove();
          setTimeout(() => {
            try {
              openFoxJudgePanel();
            } catch {}
          }, 50);
        }
      },
    });
    ssBindTagPairsEditor("foxjudge-inc", o);
    ssBindTagPairsEditor("foxjudge-exc", o);
    let s = false;
    o.querySelector("#foxjudge-enabled").onchange = async (e) => {
      if (s) {
        e.target.checked = !e.target.checked;
        return;
      }
      s = true;
      const t = e.target.checked;
      let n = false;
      if (t) {
        const e = foxJudgeReadConfig();
        if (e.nativeThinking) {
          e.nativeThinking = false;
          foxJudgeSaveConfig(e);
          try {
            await foxJudgeRestoreNativePreset();
          } catch (e) {
            log("[狐裁] 切换内置时还原原生条目失败", e);
          }
          const t = o.querySelector("#foxjudge-native-enabled");
          if (t) t.checked = false;
          toast("🧠 已关闭原生思维链，切换到内置思维链", "info");
          n = true;
        }
      } else {
        const e = o.querySelector("#foxjudge-native-enabled");
