            toast("❌ 不是有效的快照文件", "error");
            return;
          }
          const cur = foxVaultLoad(k);
          const ids = new Set(cur.items.map((e) => String(e.id)));
          let added = 0;
          for (const it of src.items) {
            if (!it || !it.data) continue;
            if (ids.has(String(it.id))) it.id = `${it.id}_imp${added}`;
            cur.items.push(it);
            added++;
          }
          foxVaultWrite(cur);
          toast(`📥 已导入 ${added} 份快照`, "success");
          try {
            after?.();
          } catch {}
        } catch (e) {
          toast(`❌ 导入失败：${e?.message || e}`, "error");
        }
      };
      input.click();
      return true;
    } catch (e) {
      log("[快照保险箱] 导入失败", e);
      return false;
    }
