  /* ---------- 记忆救援：把已经丢了的老记忆捞回来 ---------- */
  function foxMemRescueCandidates() {
    const out = [];
    const push = (o) => {
      try {
        if (!o || !o.counts) return;
        const c = o.counts;
        if ((c.memories || 0) + (c.atoms || 0) <= 0) return;
        out.push(o);
      } catch {}
    };
    const countsOf = (lib) => _foxVaultCountsOfMem(lib);
    const pushLib = (label, source, lib, extra = {}) => {
      try {
        const c = Array.isArray(lib?.memories)
          ? {
              memories: lib.memories.length,
              atoms: Array.isArray(lib.plotAtoms) ? lib.plotAtoms.length : 0,
              profiles: Object.keys(lib.characterProfiles || {}).length,
              rels: Array.isArray(lib.relationships) ? lib.relationships.length : 0,
            }
          : countsOf(lib);
        push({
          id: `${source}::${extra.scope || ""}::${out.length}`,
          label,
          source,
          scope: extra.scope || "",
          at: extra.at || "",
          counts: c,
          data: lib,
          ...extra,
        });
      } catch {}
    };
    // 1) 当前记忆库里残留的检查点（清空后它们通常还在，是最重要的救援来源）
    try {
      const cur = loadFoxMemory();
      const cps = [
        ...(cur.checkpoints?.turns || []).map((e) => ({ ...e, __kind: "turn" })),
        ...(cur.checkpoints?.chunks || []).map((e) => ({ ...e, __kind: "chunk" })),
      ];
      for (const cp of cps) {
        if (!cp?.core) continue;
        const c = countsOf(cp.core);
        if (c.memories + c.atoms <= 0) continue;
        push({
          id: `ckpt::${cp.floor}::${cp.__kind}::${cp.swipeId || 0}::${cp.at || cp.createdAt || ""}`,
          label: `🕘 当前记忆库内的${cp.__kind === "chunk" ? "分块" : "回合"}检查点（第 ${cp.floor} 楼）`,
          source: "checkpoint",
          scope: "current",
          at: cp.createdAt || "",
          counts: c,
          data: { ...cp.core, checkpoints: { turns: [], chunks: [] } },
          floor: Number(cp.floor) || 0,
        });
      }
    } catch (e) {
      log("[记忆救援] 读取检查点失败", e);
    }
    // 2) 其它作用域 / 孤儿 key 的记忆库（换聊天、换角色卡、改卡名后遗留的数据）
    try {
      const curKey = getFoxMemoryStorageKey();
      const keys = [];
      for (let i = 0; i < r.length; i++) {
        const k = r.key(i);
        if (!k || typeof k !== "string") continue;
        if (!k.startsWith("SPreset_FoxMemory_")) continue;
        if (k === curKey) continue;
        if (
          k === "SPreset_FoxMemoryConfig" ||
          k.startsWith("SPreset_FoxMemory_AntiSycophant") ||
          k.startsWith("SPreset_FoxMemory_FieldLocks") ||
          k.startsWith("SPreset_FoxMemory_ChunkPointer") ||
          k.startsWith("SPreset_FoxMemory_AnalyzedFloors") ||
          k.startsWith("SPreset_FoxMemoryAutoCounter") ||
          k.startsWith("SPreset_FoxMemory_FloorsVer") ||
          k.startsWith("SPreset_FoxMemoryInject") ||
          k.startsWith("SPreset_FoxMemoryContextFloors") ||
          k.startsWith("SPreset_FoxMemoryPushContextFloors")
        )
          continue;
        keys.push(k);
      }
      for (const k of keys) {
        try {
          const raw = r.getItem(k);
          if (!raw) continue;
          const lib = JSON.parse(raw);
          let scope = "";
          try {
            scope = decodeURIComponent(k.replace("SPreset_FoxMemory_", ""));
          } catch {
            scope = k;
          }
          pushLib(
            `🗂️ 另一份记忆库：${scope.slice(0, 60)}`,
            "orphan_key",
            lib,
            { scope, at: lib.lastAnalysis || "", key: k },
          );
        } catch {}
      }
    } catch (e) {
      log("[记忆救援] 扫描孤儿 key 失败", e);
    }
    // 3) localStorage 兜底副本（__bak_）
    try {
      const curKey = getFoxMemoryStorageKey();
      const baks = [];
      for (let i = 0; i < localStorage.length; i++) {
        const k = localStorage.key(i);
        if (!k || !k.startsWith("__bak_SPreset_FoxMemory_")) continue;
        if (k === `__bak_${curKey}`) continue;
        baks.push(k);
      }
      for (const k of baks) {
        try {
          const raw = localStorage.getItem(k);
          if (!raw) continue;
          const lib = JSON.parse(raw);
          pushLib(
            `💾 浏览器兜底副本：${k.replace("__bak_SPreset_FoxMemory_", "").slice(0, 50)}`,
            "local_backup",
            lib,
            { scope: k, key: k.replace(/^__bak_/, "") },
          );
        } catch {}
      }
    } catch (e) {
      log("[记忆救援] 扫描兜底副本失败", e);
    }
    // 4) 保险箱里的快照
    try {
      for (const it of foxVaultLoad("mem").items) {
        const c = it.counts || _foxVaultCountsOfMem(it.data);
        if ((c.memories || 0) + (c.atoms || 0) <= 0) continue;
        out.push({
          id: `vault::${it.id}`,
          label: `🛟 快照保险箱：${it.reason}（${new Date(it.at).toLocaleString("zh-CN")}）`,
          source: "vault",
          scope: it.scope || "",
          at: it.atText || "",
          counts: c,
          data: it.data,
          floor: it.floor,
          vaultId: it.id,
        });
      }
    } catch {}
    // 5) 旧版「角色卡配置」存档里可能留着一份更早的记忆库副本
    //    （旧版本会把 SPreset_ 前缀的键一起存进角色卡槽位，正是老用户丢库后的救命稻草）
    try {
      const raws = [];
      try {
        const a = r.getItem("SPreset_PerCharStore_v1");
        if (a) raws.push(a);
      } catch {}
      try {
        const b = localStorage.getItem("SPreset_PerCharStore_v1__bak");
        if (b) raws.push(b);
      } catch {}
      const seenScopes = new Set();
      for (const raw of raws) {
        let store = null;
        try {
          store = JSON.parse(raw);
        } catch {
          continue;
        }
        for (const [charId, slot] of Object.entries(store?.slots || {})) {
          const keys = slot?.keys || {};
          for (const [k, v] of Object.entries(keys)) {
            if (!k.startsWith("SPreset_FoxMemory_")) continue;
            if (k.includes("AntiSycophant")) continue;
            if (typeof v !== "string" || !v) continue;
            let lib = null;
            try {
              lib = JSON.parse(v);
            } catch {
              continue;
            }
            let scope = k.replace("SPreset_FoxMemory_", "");
            try {
              scope = decodeURIComponent(scope);
            } catch {}
            const dedupe = `${charId}::${scope}::${v.length}`;
            if (seenScopes.has(dedupe)) continue;
            seenScopes.add(dedupe);
            pushLib(
              `🗃️ 角色卡配置存档里的旧记忆库：${scope.slice(0, 52)}`,
              "perchar_slot",
              lib,
              {
                scope,
                key: k,
                at: slot?.savedAt
                  ? new Date(Number(slot.savedAt)).toISOString()
                  : "",
              },
            );
          }
        }
      }
    } catch (e) {
      log("[记忆救援] 扫描角色卡配置存档失败", e);
    }
    // 6) 旧版「当前提示词注入」里残留的记忆文本（只能作为线索）
    try {
      const txt = r.getItem("SPreset_FoxMemoryInjectCurrentPrompt");
      if (txt && String(txt).length > 200) {
        push({
          id: "inject_text",
          label: "📝 旧版注入文本残留（仅供人工核对，不能一键恢复）",
          source: "inject_text",
          counts: { memories: 0, atoms: 0, profiles: 0, rels: 0 },
          data: null,
          textOnly: String(txt).slice(0, 4000),
        });
      }
    } catch {}
    out.sort(
      (a, b) =>
        (b.counts.memories || 0) +
        (b.counts.atoms || 0) -
        ((a.counts.memories || 0) + (a.counts.atoms || 0)),
    );
    return out.slice(0, 40);
  }
  // 从「文件存储 / 备份文件夹」里把历史记忆库捞回保险箱（异步，用户在救援页手动点）
  async function foxMemRescueScanFolder() {
    try {
      if (typeof H === "undefined" || !H) {
        toast("⚠️ 未启用「文件存储」功能，无法扫描备份文件夹", "warning");
        return 0;
      }
      try {
        if (typeof H.isActive === "function" && !H.isActive()) {
          if (typeof H.hasSavedHandle === "function" && H.hasSavedHandle()) {
            await H.ensureReady();
          }
        }
      } catch {}
      if (typeof H.isActive !== "function" || !H.isActive()) {
        toast(
          "⚠️ 请先在「文件存储」里选择并授权备份文件夹，然后重试",
          "warning",
        );
        return 0;
      }
      const all = await H.importAllFromFolder();
      let n = 0;
      for (const [mod, obj] of Object.entries(all || {})) {
        if (!obj || typeof obj !== "object") continue;
        for (const [k, v] of Object.entries(obj)) {
          if (!k.startsWith("SPreset_FoxMemory_")) continue;
          if (k.includes("AntiSycophant")) continue;
          if (k === "SPreset_FoxMemoryConfig") continue;
          if (typeof v !== "string" || !v) continue;
          try {
            const lib = JSON.parse(v);
            const c = _foxVaultCountsOfMem(lib);
            if (c.memories + c.atoms <= 0) continue;
            let scope = k.replace("SPreset_FoxMemory_", "");
            try {
              scope = decodeURIComponent(scope);
            } catch {}
            _foxVaultPush("mem", lib, `备份文件夹取回（${mod}）`, {
              scopeId: scope,
              force: true,
            });
            n++;
          } catch {}
        }
      }
      toast(
        n
          ? `📥 已从备份文件夹取回 ${n} 份记忆库到保险箱（请在列表里选择恢复）`
          : "备份文件夹里没有找到狐忆记忆库数据",
        n ? "success" : "info",
      );
      return n;
    } catch (e) {
      log("[记忆救援] 扫描备份文件夹失败", e);
      toast(`❌ 扫描备份文件夹失败：${e?.message || e}`, "error");
      return 0;
    }
  }
  function foxMemRescueApply(cand) {    try {
      if (!cand || !cand.data) {
        toast("⚠️ 该来源只能人工核对，无法一键恢复", "warning");
        return false;
      }
      const cur = loadFoxMemory();
      foxMemVaultCaptureLive("救援前自动快照", { force: true });
      const src = _foxVaultNormalizeMemPayload(cand.data);
      const next = {
        ...cur,
        memories: _foxVaultUnionById(
          src.memories,
          cur.memories || [],
          (e) => String(e?.id || `${e?.category || ""}::${e?.title || ""}`),
          NaN,
        ),
        plotAtoms: _foxVaultUnionById(
          src.plotAtoms,
          cur.plotAtoms || [],
          (e) =>
            String(
              e?.id ||
                (typeof foxMemoryAtomFingerprint === "function"
                  ? foxMemoryAtomFingerprint(e)
                  : `${e?.floorStart}-${e?.floorEnd}`),
            ),
          NaN,
        ),
        characterProfiles: {
          ...(cur.characterProfiles || {}),
          ...(src.characterProfiles || {}),
        },
        relationships:
          typeof foxMemoryMergeRelations === "function"
            ? foxMemoryMergeRelations(
                src.relationships || [],
                cur.relationships || [],
              )
            : [...(cur.relationships || []), ...(src.relationships || [])],
      };
      _foxMemAllowEmptyWrite("rescue");
      const ok = saveFoxMemory(next);
      if (!ok) {
        toast("❌ 救援写入被拒绝（详见控制台日志）", "error");
        return false;
      }
      const c = _foxVaultCountsOfMem(next);
      try {
        foxMemoryRenderList();
        foxMemoryRenderStats();
      } catch {}
      try {
        if (pt?.injectToPreset) foxMemorySyncToPreset();
      } catch {}
      toast(
        `🛟 已合并恢复：记忆 ${c.memories} 条 · 信息句 ${c.atoms} 条（原库内容未被删除）`,
        "success",
      );
      return true;
    } catch (e) {
      log("[记忆救援] 恢复失败", e);
      toast(`❌ 恢复失败：${e?.message || e}`, "error");
      return false;
    }
  }
