        (cur.memories || []).length + (cur.plotAtoms || []).length > 0
      )
        return false;
      const cps = [
        ...(cur.checkpoints?.turns || []),
        ...(cur.checkpoints?.chunks || []),
      ];
      for (const cp of cps) {
        const c = _foxVaultCountsOfMem(cp?.core);
        if (c.memories + c.atoms > 0) return true;
      }
      for (let i = 0; i < r.length; i++) {
        const k = r.key(i);
        if (k && k.startsWith("SPreset_FoxMemory_") && !k.includes("AntiSycophant")) {
          if (k === getFoxMemoryStorageKey()) continue;
          return true;
        }
