               <button id="fox-vault-imp" style="padding:6px 12px;border:1px solid rgba(255,255,255,.16);border-radius:8px;background:rgba(255,255,255,.04);color:#c8b8ae;cursor:pointer;font-size:12px;font-family:inherit;">📥 导入快照</button>
               <button id="fox-vault-trim" style="padding:6px 12px;border:1px solid rgba(255,255,255,.16);border-radius:8px;background:rgba(255,255,255,.04);color:#c8b8ae;cursor:pointer;font-size:12px;font-family:inherit;">🧹 只保留最近 5 份</button>`;
        if (curTab === "rescue") {
          body.innerHTML = `<div style="font-size:12px;color:#a09088;line-height:1.7;padding:10px 0;">
            这里用于救回<b>已经被清空/覆盖</b>的记忆。点上面的「扫描可救援的记忆」，把找到的来源合并回当前记忆库（<b>只增不减</b>，不会破坏现有内容）。<br>
            <span style="color:#f0a070;">提示：</span>记忆库被清空后，旧的「检查点」通常还在里面 —— 这是最容易救回的一条路，越早扫描越好（之后每聊一轮，检查点会被新的挤掉）。
          </div><div id="fox-vault-rescue-list"></div>`;
          setTimeout(() => {
            const scan = () => {
              const list = R.getElementById("fox-vault-rescue-list");
              if (!list) return;
              const cands = foxMemRescueCandidates();
              if (!cands.length) {
                list.innerHTML =
                  '<div style="text-align:center;color:#8a7f78;font-size:12px;padding:18px;">没有扫描到可救援的记忆</div>';
                return;
              }
              list.innerHTML = cands
                .map(
                  (c) => `<div style="border:1px solid rgba(232,120,74,.18);border-radius:10px;padding:9px 11px;margin-bottom:8px;background:rgba(255,255,255,.02);">
                <div style="display:flex;justify-content:space-between;gap:8px;flex-wrap:wrap;align-items:center;">
                  <div style="font-size:12px;color:#e8ddd4;">${escapeHtml(c.label)}</div>
                  <button data-rescue="${escapeHtml(c.id)}" style="padding:5px 10px;border:1px solid rgba(104,190,125,.45);border-radius:6px;background:rgba(104,190,125,.14);color:#9ad8a8;cursor:pointer;font-size:11px;font-family:inherit;${c.data ? "" : "opacity:.5;"}">⤺ 合并恢复</button>
                </div>
                <div style="margin-top:5px;font-size:11px;color:#a09088;">${escapeHtml(_foxVaultCountText("mem", c.counts))}${c.scope ? ` · 来源作用域：${escapeHtml(String(c.scope).slice(0, 70))}` : ""}</div>
                ${c.textOnly ? `<pre style="max-height:120px;overflow:auto;white-space:pre-wrap;font-size:11px;color:#90756a;background:rgba(0,0,0,.25);border-radius:8px;padding:8px;margin-top:6px;">${escapeHtml(c.textOnly)}</pre>` : ""}
              </div>`,
                )
                .join("");
              list.querySelectorAll("[data-rescue]").forEach((btn) => {
                btn.onclick = () => {
                  const c = cands.find((x) => String(x.id) === btn.dataset.rescue);
                  if (!c) return;
                  const okc = D?.confirm
