              folderBtn.onclick = async () => {
                folderBtn.textContent = "⏳ 读取备份文件夹…";
                await foxMemRescueScanFolder();
                folderBtn.textContent = "📁 从备份文件夹取回";
                scan();
              };
            scan();
          }, 0);
          return;
        }
        const items = foxMemVaultList(kind);
        body.innerHTML = items.length
          ? `<div style="font-size:11px;color:#8a7f78;padding:10px 0;">共 ${items.length} 份快照（按时间倒序，最多保留 ${FOX_VAULT_MAX_ITEMS} 份）</div>` +
            items.map((it) => _foxVaultRowHtml(kind, it)).join("")
          : `<div style="text-align:center;color:#8a7f78;font-size:12px;padding:24px;">还没有快照。<br>每次狐忆分析、每次会让记忆变少的写入之前，都会自动留档一份。</div>`;
        body.querySelectorAll("[data-vault-merge]").forEach((btn) => {
          btn.onclick = () => {
            const okc = D?.confirm
              ? D.confirm(
