                )
              : true;
            if (!okc) return;
            if (foxMemVaultRestore(btn.dataset.vaultMerge, kind, "merge"))
              render();
          };
        });
        body.querySelectorAll("[data-vault-replace]").forEach((btn) => {
          btn.onclick = () => {
            const okc = D?.confirm
              ? D.confirm(
