                )
              : true;
            if (!okc) return;
            if (foxMemVaultRestore(btn.dataset.vaultReplace, kind, "replace"))
              render();
          };
        });
        body.querySelectorAll("[data-vault-del]").forEach((btn) => {
          btn.onclick = () => {
            const okc = D?.confirm ? D.confirm("删除这份快照？") : true;
            if (!okc) return;
            foxMemVaultDelete(btn.dataset.vaultDel, kind);
            render();
          };
        });
        const bind = (id, fn) => {
          const el = R.getElementById(id);
          if (el) el.onclick = fn;
        };
        bind("fox-vault-now", () => {
          const it =
            kind === "pw"
              ? pwVaultCaptureLive("手动快照", { force: true, allowEmpty: true })
              : foxMemVaultCaptureLive("手动快照", { force: true, allowEmpty: true });
          toast(it ? "📸 已保存一份快照" : "⚠️ 当前没有内容可保存", it ? "success" : "warning");
          render();
        });
        bind("fox-vault-exp", () => foxMemVaultExport(kind));
        bind("fox-vault-imp", () => foxMemVaultImport(kind, render));
        bind("fox-vault-trim", () => {
          foxMemVaultTrim(5);
          render();
        });
      };
      tabs.onclick = (e) => {
        const b = e.target?.closest?.("[data-vault-tab]");
        if (!b) return;
        curTab = b.dataset.vaultTab;
        render();
      };
      box.appendChild(head);
      box.appendChild(tabs);
      box.appendChild(bar);
      box.appendChild(body);
      wrap.appendChild(box);
      R.body.appendChild(wrap);
      _foxVaultDialogEl = wrap;
      wrap.addEventListener("pointerdown", (e) => {
        if (e.target === wrap) foxMemVaultCloseDialog();
      });
      R.getElementById("fox-vault-x").onclick = () => foxMemVaultCloseDialog();
      render();
      return true;
    } catch (e) {
      log("[快照保险箱] 打开面板失败", e);
      toast(`❌ 打开失败：${e?.message || e}`, "error");
      return false;
    }
  }
