dth:100%;box-sizing:border-box;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.15);border-radius:6px;color:#e8ddd4;padding:5px 8px;font-size:12px;"></div>\n            <div><label style="font-size:11px;color:#706058;">存在惩罚</label><input id="foxmem-api-pres-pen" type="number" min="-2" max="2" step="0.01" value="${escapeHtml(o.customApi.presence_penalty ?? "")}" style="width:100%;box-sizing:border-box;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.15);border-radius:6px;color:#e8ddd4;padding:5px 8px;font-size:12px;"></div>\n          </div>\n        </details>\n        ${ssRenderJsonFormatControls("foxmem", o.customApi.extraBodyParamsYaml)}\n        ${ssRenderExtraParamsPanelHtml("foxmem", { extraBodyParamsYaml: o.customApi.extraBodyParamsYaml, excludeBodyParamsYaml: o.customApi.excludeBodyParamsYaml, extraHeadersYaml: o.customApi.extraHeadersYaml })}\n        <div style="display:flex;gap:6px;margin-top:8px;flex-wrap:wrap;align-items:center;">\n          <select id="foxmem-saved-api-select" style="flex:1;min-width:160px;box-sizing:border-box;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.15);border-radius:6px;color:#e8ddd4;padding:5px 8px;font-size:12px;">${ssGetCustomApiPresetOptionsHtml()}</select>\n          <button id="foxmem-saved-api-apply" style="padding:5px 10px;border:1px solid rgba(232,120,74,0.25);border-radius:6px;background:rgba(232,120,74,0.08);color:#f0a070;cursor:pointer;font-size:11px;">填入</button>\n          <button id="foxmem-saved-api-save" style="padding:5px 10px;border:1px solid rgba(232,120,74,0.25);border-radius:6px;background:rgba(255,255,255,0.03);color:#a09088;cursor:pointer;font-size:11px;">保存</button>\n          <button id="foxmem-saved-api-delete" style="padding:5px 10px;border:1px solid rgba(139,0,0,0.3);border-radius:6px;background:rgba(139,0,0,0.12);color:#d08080;cursor:pointer;font-size:11px;">删除</button>\n        </div>\n      </div>\n    </div>\n\n    \x3c!-- ====== 第二层：向量语义召回 ====== --\x3e\n    <details style="background:rgba(232,120,74,0.035);border:1px solid rgba(232,120,74,0.15);border-radius:12px;">\n      <summary style="cursor:pointer;padding:14px 16px;font-weight:600;color:#f0a070;font-size:14px;user-select:none;">🧭 向量语义召回</summary>\n      <div style="padding:0 16px 16px;">\n      <div style="font-size:11px;color:#90756a;line-height:1.6;margin-bottom:10px;">把记忆信息句与当前查询分别向量化，用语义相似度（而非关键词）召回相关记忆；与关键词/实体打分加权融合。查询拆成最多 3 路语义变体分别召回取最高分。楼层窗口跟随狐忆「召回楼层数」；单路查询字数可自定义（0=不限制）。远程 API 默认前端直连上游（同柏宝书，免 CSRF/代理），失败自动回退酒馆代理（需 enableCorsProxy: true）。</div>\n      <label style="display:flex;align-items:center;justify-content:space-between;margin-bottom:8px;color:#ffd8b8;font-size:12px;">\n        <span>启用向量语义召回</span>\n        <input id="foxmem-vector-enabled" type="checkbox" ${o.vectorMemory?.enabled ? "checked" : ""}>\n      </label>\n      <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px 12px;margin-bottom:8px;">\n        <div><label style="font-size:11px;color:#706058;">连接方式</label><select id="foxmem-vector-mode" style="width:100%;box-sizing:border-box;background:rgba(255,255,255,.04);border:1px solid rgba(232,120,74,.15);border-radius:6px;color:#e8ddd4;padding:6px 8px;"><option value="custom" ${!o.vectorMemory?.proxyPreset ? "selected" : ""}>直接配置</option><option value="proxy" ${o.vectorMemory?.proxyPreset ? "selected" : ""}>借用酒馆代理预设</option></select></div>\n        <div id="foxmem-vector-proxy-wrap" style="display:${o.vectorMemory?.proxyPreset ? "block" : "none"};"><label style="font-size:11px;color:#706058;">代理预设</label><select id="foxmem-vector-proxy-preset" style="width:100%;box-sizing:border-box;background:rgba(255,255,255,.04);border:1px solid rgba(232,120,74,.15);border-radius:6px;color:#e8ddd4;padding:6px 8px;">${u}</select></div>\n      </div>\n      <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px 12px;">\n        <div id="foxmem-vector-endpoint-wrap" style="display:${o.vectorMemory?.proxyPreset ? "none" : "block"};"><label style="font-size:11px;color:#706058;">Embedding API 地址</label><input id="foxmem-vector-endpoint" type="text" placeholder="https://api.example.com/v1" value="${escapeHtml(o.vectorMemory?.endpoint || "")}" style="width:100%;box-sizing:border-box;background:rgba(255,255,255,.04);border:1px solid rgba(232,120,74,.15);border-radius:6px;color:#e8ddd4;padding:6px 8px;"></div>\n        <div id="foxmem-vector-key-wrap" style="display:${o.vectorMemory?.proxyPreset ? "none" : "block"};"><label style="font-size:11px;color:#706058;">API Key</label><input id="foxmem-vector-key" type="password" value="${escapeHtml(o.vectorMemory?.apiKey || "")}" style="width:100%;box-sizing:border-box;background:rgba(255,255,255,.04);border:1px solid rgba(232,120,74,.15);border-radius:6px;color:#e8ddd4;padding:6px 8px;"></div>\n        <div><label style="font-size:11px;color:#706058;">Embedding 模型</label><div style="display:flex;gap:6px;"><input id="foxmem-vector-model" type="text" placeholder="text-embedding-3-small" value="${escapeHtml(o.vectorMemory?.model || "")}" style="flex:1;min-width:0;box-sizing:border-box;background:rgba(255,255,255,.04);border:1px solid rgba(232,120,74,.15);border-radius:6px;color:#e8ddd4;padding:6px 8px;"><button id="foxmem-vector-fetch-models" type="button" style="padding:6px 10px;border:1px solid rgba(232,120,74,.2);border-radius:6px;background:rgba(255,255,255,.03);color:#a09088;cursor:pointer;white-space:nowrap;">获取模型</button></div></div>\n        <div><label style="font-size:11px;color:#706058;">模型列表</label><select id="foxmem-vector-model-select" style="width:100%;box-sizing:border-box;background:rgba(255,255,255,.04);border:1px solid rgba(232,120,74,.15);border-radius:6px;color:#e8ddd4;padding:6px 8px;"><option value="">（获取后选择）</option></select></div>\n        <div><label style="font-size:11px;color:#706058;">向量权重（0-0.8）</label><input id="foxmem-vector-weight" type="number" min="0" max="0.8" step="0.05" value="${o.vectorMemory?.weight ?? 0.