      const E = `【本次必须补齐/更新的剧情摘要板块】\n${k}\n\n【本次目标板块旧内容】\n${S}\n\n【相邻前序板块，仅用于时间线衔接，禁止重写】\n${A}\n\n【已有剧情摘要板块索引】\n${w}${M}`;
      const I = c.length
