      const z = pwGraphGetPlayerName();
      const L = `你是长期记忆库管理助手。你必须维护一个结构化长期记忆库。\n请根据上下文中的完整内容，同步更新长期记忆库。\n\n${foxMemoryBuildExtractionControlPrompt(pt)}\n`;
      const N = `${L}\n\n【上下文开始】`;
      const D = foxMemoryNormalizeExtractionSettings(pt);
      const R =
        pt.apiType === "custom" &&
