  // §21.4-1：狐搜「连接自检」——把「不确定成没成功」变成自助诊断
  async function husouRunConnectionSelfCheck() {
    const lines = [];
    const push = (ok, text) => lines.push(`${ok === true ? "✅" : ok === false ? "❌" : "•"} ${text}`);
    let cfg = null;
    try {
      cfg = S.husouSettings || loadHusouSettings();
    } catch {}
    if (!cfg) {
      toast("❌ 读取狐搜设置失败", "error");
      return;
    }
    const rawUrl = String(cfg.searchApiUrl || "").trim();
    push(rawUrl ? true : false, rawUrl ? `自定义来源 URL：${husouSafeUrl(rawUrl)}` : "未配置自定义来源 URL（仅基础模式可跳过本项）");
    if (!rawUrl) {
      push(null, "基础模式依赖 Wikipedia / 萌娘百科，若它们不通请配置自定义来源 API");
      husouShowSelfCheckResult(lines);
      return;
    }
    if (!/\{keyword\}/.test(rawUrl))
      push(false, "URL 缺少 {keyword} 占位符 —— SearXNG 会把它当固定查询词，可能返回空结果");
    else push(true, "URL 含 {keyword} 占位符");
    if (!/format=json/.test(rawUrl))
      push(false, "URL 缺少 format=json —— 后端会返回 HTML，脚本解析必然失败");
    else push(true, "URL 含 format=json");
    const testUrl = rawUrl
      .replace(/\{keyword\}/g, encodeURIComponent("test"))
      .replace(/\{language\}/g, encodeURIComponent("zh-CN"));
    push(null, `自检请求：${husouSafeUrl(testUrl)}`);
    const ctrl = new AbortController();
    const timer = setTimeout(() => {
      try {
        ctrl.abort();
      } catch {}
    }, Math.max(5e3, Number(cfg.searchTimeout) || 2e4));
    try {
      const res = await fetch(testUrl, {
        method: "GET",
        signal: ctrl.signal,
        headers: cfg.searchApiKey
          ? { [cfg.searchApiKeyHeaderName || "Authorization"]: cfg.searchApiKeyHeaderTemplate ? cfg.searchApiKeyHeaderTemplate.replace(/\{key\}/g, cfg.searchApiKey) : cfg.searchApiKey }
          : undefined,
      });
      clearTimeout(timer);
      push(res.ok, `HTTP 状态：${res.status} ${res.statusText || ""}`);
      const ct = String(res.headers.get("content-type") || "");
      push(/json/i.test(ct), `Content-Type：${ct || "(空)"}${/json/i.test(ct) ? "" : " —— 不是 JSON，请确认 settings.yml 的 search.formats 含 json"}`);
      let text = "";
      try {
        text = await res.text();
      } catch {}
      let data = null;
      try {
        data = JSON.parse(text);
      } catch {}
      if (!data) {
        push(false, `响应不是合法 JSON（前 120 字）：${String(text).slice(0, 120)}`);
      } else {
        const path = String(cfg.searchApiResultPath || "results").trim() || "results";
        const arr = path
          .split(".")
          .filter(Boolean)
          .reduce((o, k) => (o == null ? o : o[k]), data);
        if (Array.isArray(arr)) {
          push(true, `results 结构正常（${path} 数组长度 ${arr.length}）`);
          if (arr.length) {
            const f = arr[0] || {};
            const tf = String(cfg.searchApiTitleField || "title");
            const lf = String(cfg.searchApiLinkField || "url");
            push(!!f[tf], `标题字段「${tf}」${f[tf] ? "有值" : "取不到值（请检查字段名映射）"}`);
            push(!!f[lf], `链接字段「${lf}」${f[lf] ? "有值" : "取不到值（请检查字段名映射）"}`);
          }
        } else {
          push(false, `results 结构异常：${path} 不是数组（请检查「结果路径」配置）`);
        }
      }
      // CORS：浏览器端能拿到响应体即说明未被拦截（不透明响应读不到 text）
      push(text.length > 0, text.length > 0 ? "CORS：可读取响应体（未被跨域拦截）" : "CORS：响应体为空，可能被跨域策略拦截或需要 Access-Control-Allow-Origin");
    } catch (e) {
      clearTimeout(timer);
      const msg = e?.message || String(e);
      if (/abort/i.test(msg))
        push(false, `请求超时（>${Math.max(5e3, Number(cfg.searchTimeout) || 2e4)}ms）—— 检查地址/端口/防火墙`);
      else push(false, `请求失败：${msg}（常见原因：CORS 未放行 / HTTP 页面请求 HTTP 之外的后端 / 混合内容被拦截 / 端口错`);
    }
    husouShowSelfCheckResult(lines);
  }
