nt;border:1px solid rgba(232,120,74,.26)!important;border-radius:8px!important;padding:7px 26px 7px 10px!important;font-size:11.5px!important;font-family:inherit!important;outline:none!important;cursor:pointer!important;box-sizing:border-box!important;transition:all .2s!important}\n#ss-husou-panel select:hover{border-color:rgba(240,160,112,.48)!important;background-color:#241a14!important}\n#ss-husou-panel select option,#ss-husou-panel select optgroup{background-color:#1a1411!important;color:#e8ddd4!important;font-family:inherit!important;font-size:12px!important;padding:4px 8px!important}\n#ss-husou-panel select option:checked{background-color:rgba(232,120,74,.28)!important;color:#fff5e8!important}\n#ss-husou-panel .mb-top,#ss-husou-panel .mb-dock{display:none}\n@media(max-width:720px){\n#ss-husou-panel{position:fixed!important;top:0!important;left:0!important;transform:none!important;width:100vw!important;height:100dvh!important;max-width:none!important;max-height:none!important;min-width:0!important;min-height:0!important;border-radius:0!important;padding:0!important;overflow:hidden!important}\n#ss-husou-panel .pc-head,#ss-husou-panel .work>.rail{display:none!important}\n#ss-husou-panel .work{padding:0;flex:1;min-height:0;flex-direction:column}\n#ss-husou-panel .work>.main{flex:1;min-width:0;overflow-y:auto;padding:14px 13px 70px}\n#ss-husou-panel .mb-top{display:flex!important;padding:10px 13px;align-items:center;gap:10px;border-bottom:1px solid rgba(232,120,74,.12);background:rgba(0,0,0,.3);position:relative;flex-shrink:0}\n#ss-husou-panel .mb-top::after{content:"";position:absolute;left:8%;right:8%;bottom:-1px;height:1px;background:linear-gradient(90deg,transparent,rgba(232,120,74,.5),transparent)}\n#ss-husou-panel .mb-back{width:34px;height:34px;border-radius:10px;border:1px solid rgba(255,255,255,.1);background:rgba(255,255,255,.04);color:#8a7f78;cursor:pointer;font-size:15px;display:flex;align-items:center;justify-content:center;flex-shrink:0}\n#ss-husou-panel .mb-title{flex:1;min-width:0}\n#ss-husou-panel .mb-title h1{font-size:15px;font-weight:700;color:#e8ddd4}\n#ss-husou-panel .mb-title p{font-size:10px;color:#706058;margin-top:1px}\n#ss-husou-panel .mb-right{display:flex;gap:6px}\n#ss-husou-panel .mb-dock{flex-shrink:0;background:rgba(8,6,5,.96);backdrop-filter:blur(14px);border-top:1px solid rgba(232,120,74,.18);display:flex;align-items:stretch;justify-content:space-around;padding:5px 4px calc(5px + env(safe-area-inset-bottom));position:relative;z-index:10}\n#ss-husou-panel .mb-dock::before{content:"";position:absolute;left:10%;right:10%;top:0;height:1px;background:linear-gradient(90deg,transparent,rgba(232,120,74,.38),transparent)}\n#ss-husou-panel .dock-item{flex:1;max-width:88px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;padding:6px 4px 4px;border-radius:11px;cursor:pointer;transition:all .2s;position:relative;border:1px solid transparent}\n#ss-husou-panel .dock-item.cur{background:linear-gradient(180deg,rgba(232,120,74,.16),rgba(232,120,74,.03));border-color:rgba(232,120,74,.32)}\n#ss-husou-panel .dock-item.cur::after{content:"";position:absolute;top:-1px;left:25%;right:25%;height:2px;border-radius:99px;background:linear-gradient(90deg,#e8784a,#f0a070);box-shadow:0 0 8px rgba(232,120,74,.7)}\n#ss-husou-panel .dock-item .d-ic{font-size:17px;line-height:1;display:flex;align-items:center;justify-content:center;width:28px;height:28px;border-radius:8px}\n#ss-husou-panel .dock-item.cur .d-ic{background:linear-gradient(135deg,rgba(232,120,74,.35),rgba(240,160,112,.15));box-shadow:0 0 10px rgba(232,120,74,.3)}\n#ss-husou-panel .dock-item .d-t{font-size:9.5px;color:#706058;font-weight:500}\n#ss-husou-panel .dock-item.cur .d-t{color:#f0a070;text-shadow:0 0 8px rgba(232,120,74,.4)}\n#ss-husou-panel .hs-cfg{grid-template-columns:1fr!important}\n}\n</style>\n<div class="mb-top">\n  <button class="mb-back" id="ss-husou-close-mb">‹</button>\n  <div class="mb-title"><h1>🔎 狐搜</h1><p id="hs-mb-sub">外部搜索 · 资料管理</p></div>\n  <div class="mb-right"></div>\n</div>\n<div class="pc-head">\n  <div class="crumb">🦊 模块中心 <i>▸</i> <b>🔎 狐搜 · 外部搜索</b></div>\n  <div class="hd-right"><span class="hd-pill"><b>网络资料搜索</b></span></div>\n  <button class="btn-x" id="ss-husou-close">✕</button>\n</div>\n<div class="work">\n  <aside class="rail">\n    <div class="rl-title">狐搜 模块</div>\n    <div class="mitem cur" data-hstab="search"><span class="mico">🔎</span><div class="mtext"><b>搜索管理</b><small>手动搜索 · 资料库</small></div></div>\n    <div class="mitem" data-hstab="config"><span class="mico">📐</span><div class="mtext"><b>搜索配置</b><small>参数 · 来源 · 标签</small></div></div>\n    <div class="mitem" data-hstab="api"><span class="mico">📡</span><div class="mtext"><b>API · 预设</b><small>分析模型 · 破限</small></div></div>\n    <div class="rl-sec">管理</div>\n    <div class="mitem" data-hstab="manage"><span class="mico">📦</span><div class="mtext"><b>资料管理</b><small>本地内容 · 操作</small></div></div>\n    <div class="stat-mini">\n      <div class="sm-label">● 狐搜状态</div>\n      <div id="search_engine_status" style="color:#706058;font-size:10px;line-height:1.5;">当前状态：🦊狐搜 已加载</div>\n    </div>\n  </aside>\n  <main class="main">\n    <section class="hs-tab-pane active" data-hspane="search">\n      <div class="m-head"><span class="mico">🔎</span><h2>搜索管理 · 手动搜索与资料</h2></div>\n<div class="husou_keyword_panel" id="husou_keyword_panel" style="background:rgba(232,120,74,0.05);border:1px solid rgba(232,120,74,0.15);border-radius:10px;padding:10px 12px;display:none;">\n<div style="display:flex;justify-content:space-between;align-items:center;"><span style="color:#f0a070;font-weight:600;">🔑 本次抓取关键词</span><span id="husou_keyword_count" style="color:#706058;font-size:0.85em;"></span></div>\n<div id="husou_keyword_list" style="color:#a09088;margin-top:4px;font-size:0.9em;word-break:break-all;"></div></div>\n<div class="husou-network-note">网络诊断：搜索失败时先访问 <code>https://r.jina.ai/</code>。若无法访问或超时，请检查当前网络或代理。</div>\n<div class="quick-bar">\n  <button class="hs-vbtn hs-vbtn-primary" onclick="document.getElementById('search_manual_btn')?.click()">🔍 手动搜索（追加）</button>\n  <button class="hs-vbtn hs-vbtn-ghost" onclick="document.getElementById('search_manual_keyword_btn')?.click()">🔎 手动关键词搜索</button>\n  <button class="hs-vbtn hs-vbtn-ghost" onclick="document.getElementById('search_test_btn')?.click()">测试面板</button>\n</div>\n</section>\n<section class="hs-tab-pane" data-hspane="config">\n  <div class="m-head"><span class="mico">📐</span><h2>搜索配置 · 参数与来源</h2></div>\n\n<div class="husou-control-card ss-husou-card">\n<div class="husou-card-heading"><span>自动任务</span><small>AUTOMATION</small></div>\n <div class="husou-auto-row"><div><strong>自动搜索</strong><small>选择 AI 回复完成后的搜索周期</small></div><div class="husou-auto-controls"><select id="search_auto_mode"><option value="manual" ${e.autoMode === "manual" ? "selected" : ""}>仅手动</option><option value="auto" ${e.autoMode === "auto" ? "selected" : ""}>每次回复后搜索</option><option value="interval" ${e.autoMode === "interval" ? "selected" : ""}>每隔 N 楼搜索</option></select><span class="husou-interval-box" style="display:${e.autoMode === "interval" ? "inline-flex" : "none"};"><input id="search_auto_interval" type="number" value="${e.autoInterval}" min="1" max="9999"><span id="search_auto_interval_label">楼</span></span></div></div>\n${xhSendAnalyzeBtnHtml("search_send_analyze", e.sendAnalyze === true)}\n<label class="husou-setting-row husou-setting-featured">\n  <span><strong style="color:#ffb06a;">🌙 后台静默更新</strong><span style="display:block;font-size:11px;color:#90756a;margin-top:4px;">AI 回复完成后在后台搜索，完成后保存并供后续对话注入。</span></span>\n  <input id="search_background_silent" type="checkbox" ${e.backgroundSilent === true ? "checked" : ""}>\n</label>\n</div>\n\n<div style="background:rgba(232,120,74,0.025);border:1px solid rgba(232,120,74,0.1);border-radius:10px;padding:12px 14px;">\n<div style="font-weight:600;margin-bottom:8px;color:#e8ddd4;">📐 搜索参数</div>\n<div style="display:grid;grid-template-columns:repeat(2,1fr);gap:8px 16px;">\n<div><label for="search_max_keywords" style="font-size:11px;color:#706058;">最多提取关键词数</label><input id="search_max_keywords" type="number" min="1" max="999" step="1" value="${e.maxKeywords || 50}" style="width:100%;box-sizing:border-box;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.15);border-radius:6px;color:#e8ddd4;padding:5px 8px;font-size:12px;"></div>\n\n<div><label for="search_timeout" style="font-size:11px;color:#706058;">基础搜索超时（毫秒）</label><input id="search_timeout" type="number" min="5000" max="60000" step="1000" value="${e.searchTimeout || 2e4}" style="width:100%;box-sizing:border-box;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.15);border-radius:6px;color:#e8ddd4;padding:5px 8px;font-size:12px;"></div>\n\n<div><label for="search_jina_page_timeout" style="font-size:11px;color:#706058;">Jina单页抓取超时（毫秒）</label><input id="search_jina_page_timeout" type="number" min="5000" max="120000" step="1000" value="${e.jinaPageTimeout || 2e4}" style="width:100%;box-sizing:border-box;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.15);border-radius:6px;color:#e8ddd4;padding:5px 8px;font-size:12px;"></div>\n\n<div><label for="search_extract_length" style="font-size:11px;color:#706058;">提取最大长度</label><input id="search_extract_length" type="number" min="1000" max="1000000" step="1000" value="${e.maxExtractLength || 4e4}" style="width:100%;box-sizing:border-box;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.15);border-radius:6px;color:#e8ddd4;padding:5px 8px;font-size:12px;"></div>\n\n<div><label for="search_results_count" style="font-size:11px;color:#706058;">每个关键词搜索结果数</label><input id="search_results_count" type="number" min="1" max="999" step="1" value="${e.searchResultsCount || 10}" style="width:100%;box-sizing:border-box;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.15);border-radius:6px;color:#e8ddd4;padding:5px 8px;font-size:12px;"></div>\n\n<div><label for="search_context_floors" style="font-size:11px;color:#706058;">AI 分析楼层限制（0=全部）</label><input id="search_context_floors" type="number" min="0" max="9999" step="1" value="${parseInt(r.getItem("SPreset_HusouContextFloors")) || 10}" style="width:100%;box-sizing:border-box;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.15);border-radius:6px;color:#e8ddd4;padding:5px 8px;font-size:12px;"></div>\n</div>\n<div class="husou-destination-list" style="display:flex;flex-direction:column;gap:8px;margin-top:10px;">\n  <div class="husou-card-heading"><span>结果去向</span><small>DESTINATION</small></div>\n  <label class="husou-setting-row husou-setting-featured">\n    <span>\n      <strong style="color:#ffb06a;">📌 插入到当前提示词（推荐）</strong>\n      <span style="display:block;font-size:11px;color:#f0a070;margin-top:4px;line-height:1.5;">\n        本次搜索结果会直接给主模型看，不写入角色卡。\n      </span>\n    </span>\n    <input id="search_inject_prompt" type="checkbox" ${e.injectCurrentPrompt ? "checked" : ""}>\n  </label>\n\n  <label class="husou-setting-row">\n    <span>\n      <strong>📦 保存到狐搜本地资料库（推荐）</strong>\n      <span style="display:block;font-size:11px;color:#706058;margin-top:4px;line-height:1.5;">\n        保存在浏览器本地，方便下次继续使用。不会改角色卡。\n      </span>\n    </span>\n    <input id="search_save_husou_local" type="checkbox" ${e.saveToHusouLocal ? "checked" : ""}>\n  </label>\n\n  <label class="husou-setting-row husou-setting-danger">\n    <span>\n      <strong>💾 写入角色卡 personality（慎用）</strong>\n      <span style="display:block;font-size:11px;color:#706058;margin-top:4px;line-height:1.5;">\n        会直接改角色卡内容。换卡或清理不及时，可能残留旧搜索结果。\n      </span>\n    </span>\n    <input id="search_save_personality" type="checkbox" ${e.saveToPersonality ? "checked" : ""}>\n  </label>\n</div></div>\n${(() => {
      const t = ssNormalizeTagFilterSettings(e);
      return `\n<div style="background:rgba(232,120,74,0.025);border:1px solid rgba(232,120,74,0.1);border-radius:10px;padding:12px 14px;">\n  <details style="border:1px solid rgba(232,120,74,0.12);border-radius:8px;background:rgba(255,255,255,0.018);padding:8px 10px;">\n    <summary style="cursor:pointer;color:#f0a070;font-size:12px;font-weight:600;user-select:none;">\n      🏷️ 狐搜上下文标签过滤\n    </summary>\n\n    <div style="font-size:11px;color:#90756a;line-height:1.6;margin:8px 0;">\n      狐搜现在会像狐构/狐忆一样读取完整固定上下文。<br>\n      固定读取顺序：charDescription → charPersonality → scenario → personaDescription → 狐析用户偏好 → worldInfoBefore → worldInfoAfter → chatHistory。<br>\n      用户消息不做标签过滤，AI/char 消息才会按这里的规则过滤。<br>\n      默认不设置包含标签，即读取完整正文；默认删除检查块、基础要求块，以及 <code>&lt;/think_fox~&gt;</code> 之前内容。\n    </div>\n\n    <label class="husou-setting-row" style="margin-bottom:8px;">\n      <span><strong>启用狐搜标签过滤</strong><small>按下方标签规则清理 AI/角色消息上下文</small></span>\n      <input type="checkbox" id="husou-content-filter" ${t.enableContentFilter !== false ? "checked" : ""}>\n    </label>\n\n    ${ssCreateTagPairsEditorHtml("husou-inc", "✅ 包含标签：只保留这些标签范围内的内容", t.includeTagPairs, "一行是一组。左边开始标签，右边结束标签。留空 = 不限制包含范围，读取完整上下文。")}\n\n    ${ssCreateTagPairsEditorHtml("husou-exc", "❌ 排除标签：删除这些标签范围内的内容", t.excludeTagPairs, "允许只填结束标签，例如结束填 </think_fox~> = 删除它之前所有内容。")}\n  </details>\n</div>`;
