  function readHusouSettingsFromPanel(e) {
    const g = (t) => e.querySelector("#" + t) || R.getElementById(t);
    const t = S.husouSettings;
    if (!t) return;
    const n = g("search_auto_mode");
    if (n) {
      t.autoMode = ["manual", "auto", "interval"].includes(n.value)
        ? n.value
        : "manual";
    }
    const o = g("search_auto_interval");
    if (o) {
      t.autoInterval = Math.max(1, parseInt(o.value) || 5);
    }
    t.enableAutoSearch = t.autoMode !== "manual";
    t.backgroundSilent = !!g("search_background_silent")?.checked;
    const a = g("search_source_mode");
    if (a) {
      if (a.value === "custom") {
        t.enableCustomSearch = true;
        t.enableWikipedia = false;
        t.enableMoegirl = false;
      } else {
        t.enableCustomSearch = false;
        t.enableWikipedia = true;
        t.enableMoegirl = true;
      }
    }
    t.enableJinaFetch = !!g("search_enable_jina")?.checked;
    t.smartSkip = !!g("search_smart_skip")?.checked;
    t.aiFilter = !!g("search_ai_filter")?.checked;
    t.saveToPersonality = !!g("search_save_personality")?.checked;
    t.injectCurrentPrompt = !!g("search_inject_prompt")?.checked;
    t.saveToHusouLocal = !!g("search_save_husou_local")?.checked;
    const s = ssNormalizeTagFilterSettings({
      enableContentFilter: !!g("husou-content-filter")?.checked,
      includeTagPairs: ssReadTagPairsEditor("husou-inc", e),
      excludeTagPairs: ssReadTagPairsEditor("husou-exc", e),
    });
    t.enableContentFilter = s.enableContentFilter;
    t.includeTagPairs = s.includeTagPairs;
    t.excludeTagPairs = s.excludeTagPairs;
    t.includeTagStarts = s.includeTagStarts;
    t.includeTagEnds = s.includeTagEnds;
    t.excludeTagStarts = s.excludeTagStarts;
    t.excludeTagEnds = s.excludeTagEnds;
    t.analysisApi = g("search_analysis_api")?.value || "current";
    t.customApiUrl = g("search_custom_api_url")?.value?.trim() || "";
    t.customApiKey = g("search_custom_api_key")?.value?.trim() || "";
    t.customModel = g("search_custom_model")?.value?.trim() || "";
    t.customMaxTokens = Number(g("search_custom_max_tokens")?.value || 4096);
    t.customTemperature = Number(g("search_custom_temperature")?.value || 1);
    t.customFrequencyPenalty = Number(
      g("search_custom_frequency_penalty")?.value || 0,
    );
    t.customPresencePenalty = Number(
      g("search_custom_presence_penalty")?.value || 0,
    );
    t.customTopP = Number(g("search_custom_top_p")?.value || 1);
    t.customTopK = Number(g("search_custom_top_k")?.value || 0);
    {
      const n = ssReadExtraParamsFromPanel("husou", e);
      t.customExtraBodyParamsYaml = n.extraBodyParamsYaml;
      t.customExcludeBodyParamsYaml = n.excludeBodyParamsYaml;
      t.customExtraHeadersYaml = n.extraHeadersYaml;
    }
    t.searchPresetMode = g("search_preset_mode")?.value || "builtin";
    t.searchPresetName = g("search_preset_name")?.value?.trim() || "";
    // §5.3-3：唯一没有兜底值的字段 —— 元素缺失或为空时会把已配置的 URL 抹成空串
    {
      const _urlEl = g("search_api_url");
