        const _v = String(_urlEl.value || "").trim();
        if (_v) t.searchApiUrl = _v;
        else if (t.searchApiUrl) {
          try {
            toast(
              "⚠️ 自定义搜索 API 地址为空，已保留原配置（如需清空请显式删除后保存）",
              "warning",
            );
          } catch {}
        } else t.searchApiUrl = "";
