    t.searchApiQueryParam = g("search_api_query_param")?.value?.trim() || "";
    t.searchApiBodyTemplate =
      g("search_api_body_template")?.value?.trim() || "";
    t.searchApiResultPath = g("search_api_result_path")?.value?.trim() || "";
