  function xhDockAction(e) {
    try {
      if (e === "fox3d") foxGraphOpen();
      else if (e === "pw3d") pwGraphOpen();
      else if (e === "foxPanel") openFoxMemoryPanel();
      else if (e === "pwPanel") pwOpenPanel();
      else if (e === "foxAnalyze") {
        if (typeof foxMemoryRunAnalyze === "function") foxMemoryRunAnalyze();
      } else if (e === "pwRun") {
        if (typeof pwRunCycle === "function") pwRunCycle(false);
      } else if (e === "pwDynamic") {
        const e = xdPwCfg();
        if (e.advanceMode === "legacy_full") {
