            "warning",
          );
          return;
        }
        if (typeof pwRunDynamicCycle === "function") pwRunDynamicCycle(false);
      } else if (e === "pwSummary") {
        if (typeof pwSummarizeOnly === "function") pwSummarizeOnly();
      } else if (e === "foxTableTpl") xhDockEditTableTemplate();
      else if (e === "foxTableTplReset") xhDockResetTableTemplate();
      else if (e === "foxTableNew") xhDockNewCustomTable();
      else if (e === "foxTableNewChar") xhDockNewCharacterProfile();
      else if (e === "foxTableSeed") xhDockSeedTemplateToAll();
