  function pwMakeFloatDraggable(e) {
    let t = false;
    let n = 0;
    let o = 0;
    let a = 0;
    let r = 0;
    const s = R.getElementById("pw-state-head");
    if (!s) return;
    const toggleHandles = (t) => {
      const n = e.querySelectorAll(".pw-resize-handle");
      n.forEach((e) => {
        e.style.pointerEvents = t ? "auto" : "none";
      });
    };
    const down = (s) => {
      if (s.target?.id === "pw-state-close") return;
      if (s.target?.classList?.contains("pw-resize-handle")) return;
      t = true;
      toggleHandles(false);
      const i = e.getBoundingClientRect();
      n = s.clientX;
      o = s.clientY;
      a = i.left;
      r = i.top;
      e.style.left = `${i.left}px`;
      e.style.top = `${i.top}px`;
      e.style.right = "auto";
      e.style.bottom = "auto";
      s.preventDefault();
    };
    const move = (s) => {
      if (!t) return;
      s.preventDefault?.();
      s.stopPropagation?.();
      const i = D.innerWidth || 900;
      const l = D.innerHeight || 700;
      const c = e.getBoundingClientRect();
      const d = Math.max(4, Math.min(i - c.width - 4, a + s.clientX - n));
      const p = Math.max(4, Math.min(l - c.height - 4, r + s.clientY - o));
      e.style.left = `${d}px`;
      e.style.top = `${p}px`;
    };
    const up = () => {
      if (!t) return;
      t = false;
      toggleHandles(true);
    };
    s.addEventListener("pointerdown", down);
    R.addEventListener("pointermove", move);
    R.addEventListener("pointerup", up);
  }
