   </div>\n\n      <div id="pw-auto-interval-wrap" style="display:${t.autoMode === "interval" ? "flex" : "none"};align-items:center;gap:8px;flex-wrap:wrap;margin-top:10px;padding-top:10px;border-top:1px solid rgba(96,210,255,0.10);">\n        <span style="font-size:12px;color:#aac0cf;">📊 每隔</span>\n        <input id="pw-auto-interval" type="number" min="1" max="999" value="${escapeHtml(t.autoInterval || 5)}" style="width:90px;flex:0 0 90px;text-align:center;">\n        <span style="font-size:12px;color:#aac0cf;">次合格回复后自动推进</span>\n      </div>\n\n      <label class="pw-switch" style="width:100%;margin-top:10px;">\n        <span>🌙 后台静默更新<span style="display:block;font-size:10px;color:#7891a2;margin-top:3px;">自动推进不显示等待弹窗；完成后更新数据并供后续对话注入。</span></span>\n        <input id="pw-background-silent" type="checkbox" ${t.backgroundSilent ? "checked" : ""}>\n      </label>\n\n      \x3c!-- ✅ 推进模式 / 动态推进上限 / 聊天楼层上限 --\x3e\n      <div style="margin-top:12px;padding-top:10px;border-top:1px solid rgba(96,210,255,0.10);display:flex;flex-direction:column;gap:10px;">\n        <div style="display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;">\n          <div>\n            <div style="font-weight:700;color:#b9f2ff;font-size:13px;">🧭 推进模式</div>\n            <div style="font-size:10px;color:#7891a2;margin-top:3px;line-height:1.5;">\n              单请求动态推进：初始化后；之后在一次请求内，只修改需要变化的几个模块，节省token。<br>\n              旧模式：每次都整轮重写所有事件\n            </div>\n          </div>\n          <select id="pw-advance-mode" style="width:auto;min-width:170px;max-width:100%;">\n            <option value="two_phase" ${t.advanceMode !== "legacy_full" ? "selected" : ""}>单请求动态推进（默认）</option>\n            <option value="legacy_full" ${t.advanceMode === "legacy_full" ? "selected" : ""}>每次更新所有事件（旧模式）</option>\n          </select>\n        </div>\n\n        <div id="pw-dynamic-max-wrap" style="display:${t.advanceMode !== "legacy_full" ? "flex" : "none"};align-items:center;gap:8px;flex-wrap:wrap;">\n          <span style="font-size:12px;color:#aac0cf;">⚡ 单次动态推进最多更新</span>\n          <input id="pw-dynamic-max" type="number" min="1" max="24" value="${escapeHtml(t.dynamicMaxModules || 4)}" style="width:80px;flex:0 0 80px;text-align:center;">\n          <span style="font-size:12px;color:#aac0cf;">个模块（默认 4）</span>\n        </div>\n\n        <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;">\n          <span style="font-size:12px;color:#aac0cf;">📜 一次推进发送</span>\n          <input id="pw-chat-history-limit" type="text" placeholder="留空 = 全部" value="${escapeHtml(t.chatHistoryLimit === "" || t.chatHistoryLimit == null ? "" : String(t.chatHistoryLimit))}" style="width:110px;flex:0 0 110px;text-align:center;">\n          <span style="font-size:12px;color:#aac0cf;">楼聊天记录</span>\n          <span style="font-size:10px;color:#7891a2;line-height:1.5;flex:1 1 100%;">留空或 all = 全部聊天记录（默认）；填正整数 N 表示只发送最近 N 楼。同时作用于整轮推进 / 动态推进 / 单条推进。</span>\n        </div>\n      </div>\n    </div>\n\n      \x3c!-- 状态日志 --\x3e\n      <div class="pw-vcard green" style="margin-bottom:0">\n        <div class="pw-vcard-header"><h3>📋 最近状态日志</h3><span class="meta">实时</span></div>\n        <div class="st-log" id="pw-status">${escapeHtml(Pa.status)}</div>\n      </div>\n    </section>\n\n    \x3c!-- ===== TAB2: 注入摘要 ===== --\x3e\n    <section class="pw-tab-pane" data-pwpane="sum">\n      <div class="m-head"><span class="mico">💉</span><h2>注入摘要 · 管理主线 prompt 注入内容</h2>\n        <span style="flex:1"></span>\n        <button class="pw-vbtn pw-vbtn-ghost" id="pw-reset-inject-text">↩️ 清除手写</button>\n        <button class="pw-vbtn pw-vbtn-ghost" id="pw-copy-inject-text">📋 复制</button>\n        <button class="pw-vbtn pw-vbtn-primary" id="pw-save-inject-text">💾 保存</button>\n      </div>\n      <div style="font-size:11px;color:#547182;line-height:1.65;margin-bottom:9px">\n        这里显示/编辑的文本就是实际会注入主线 prompt 的平行世界摘要。AI 会把这些内容作为后台世界事实参考。\n      </div>\n      <div style="border:1px solid rgba(63,185,232,.18);border-radius:13px;overflow:hidden;background:rgba(0,0,0,.32)">\n        <div style="padding:10px 13px;background:linear-gradient(90deg,rgba(63,185,232,.11),rgba(127,220,255,.03));border-bottom:1px solid rgba(63,185,232,.15);font-size:11px;color:#7fdcff;font-weight:600;display:flex;justify-content:space-between">\n          <span>🌌 主线注入摘要</span>\n          <span>📝 可手写修改 · 修改后请点保存</span>\n        </div>\n        <textarea id="pw-inject-manager" spellcheck="false" style="width:100%;min-height:400px;padding:15px 17px;background:transparent;border:none;outline:none;color:#bfd7e5;font-family:ui-monospace,Consolas,monospace;font-size:11.5px;line-height:1.85;box-sizing:border-box;resize:vertical">${escapeHtml(pwBuildInjectPlainText())}</textarea>\n      </div>\n    </section>\n\n    \x3c!-- ===== TAB3: 事件模块 ===== --\x3e\n    <section class="pw-tab-pane" data-pwpane="ev">\n      <div class="m-head"><span class="mico">🌍</span><h2>事件模块 · 后台世界演化</h2><span style="flex:1"></span>\n        <span class="pw-pill cy">共 ${(n.modules || []).length} 条</span>\n      </div>\n      ${pwRenderModulesHtml(n)}\n    </section>\n\n    \x3c!-- ===== TAB4: 思考+命运骰 ===== --\x3e\n    <section class="pw-tab-pane" data-pwpane="th">\n      <div class="m-head"><span class="mico">🧠</span><h2>思考 · 命运骰</h2><span style="flex:1"></span>\n        <span class="pw-pill purple">${t.generationMode === "quality" ? "质量模式" : "快速模式"}</span>\n      </div>\n\n      \x3c!-- 🧠 思考模式与思维链模块（整合自总览/参数配置） --\x3e\n      <div class="pw-vcard purple">\n        <div class="pw-vcard-header"><h3>🧠 平行思考模式</h3><span class="meta">质量模式 = 生成前先思考</span></div>\n        <div style="display:flex;flex-direction:column;gap:9px">\n          <div class="pw-switch-row">\n            <div class="info"><b>🧠 平行思考模式</b><small>快速=直出平行世界不思考；质量=生成前先输出审查思考块，可在下方查看</small></div>\n            <select id="pw-generation-mode" style="min-width:120px"><option value="fast" ${t.generationMode !== "quality" ? "selected" : ""}>快速模式</option><option value="quality" ${t.generationMode === "quality" ? "selected" : ""}>质量模式</option></select>\n          </div>\n          <div class="pw-switch-row" id="pw-think-modules-row" style="display:${t.generationMode === "quality" ? "flex" : "none"}">\n            <div class="info"><b>🧩 思维链模块</b><small>质量模式自动启用。点击右侧入口可拖拽排序/编辑/启停"平行世界思考"等模块</small></div>\n            <div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap;">\n              <button type="button" id="pw-think-modules-open" style="padding:7px 14px;font-size:12px;font-weight:600;border:1px solid rgba(96,210,255,0.45);border-radius:8px;background:rgba(96,210,255,0.18);color:#b9f2ff;cursor:pointer;font-family:inherit;transition:background .15s;">🧩 管理思维链模块</button>\n              <button type="button" id="pw-think-reset-quick" title="恢复为脚本内置的默认提示词与默认排序（会清空你对思维链模块的编辑与自定义排序）" style="padding:7px 14px;font-size:12px;font-weight:600;border:1px solid rgba(255,120,120,0.4);border-radius:8px;background:rgba(255,120,120,0.12);color:#e89a9a;cursor:pointer;font-family:inherit;transition:background .15s;">↩️ 恢复默认思维链</button>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      ${s}\n      ${pwRenderDiceStorytellerConfigHtml(t)}\n    </section>\n\n    \x3c!-- ===== TAB5: 参数配置 ===== --\x3e\n    <section class="pw-tab-pane" data-pwpane="cfg">\n      <div class="m-head"><span class="mico">🎚️</span><h2>参数配置 · 规模 / 模式 / 用户要求</h2><span style="flex:1"></span>\n        <button class="pw-vbtn pw-vbtn-primary" id="pw-save-cfg">💾 保存配置</button>\n      </div>\n\n      <div class="pw-vcard purple">\n        <div class="pw-vcard-header"><h3>🎚️ 难度 / 🧭 推进模式</h3><span class="meta">思考相关已移至「思考 · 命运骰」</span></div>\n        <div style="display:flex;flex-direction:column;gap:7px">\n          <div class="pw-switch-row">\n            <div class="info"><b>🎚️ 世界难度</b><small>简单=正常/缓和事件；普通=正常事件；困难=较高难度事件。</small></div>\n            <select id="pw-event-difficulty" style="min-width:120px"><option value="easy" ${t.eventDifficulty === "easy" ? "selected" : ""}>简单</option><option value="normal" ${(t.eventDifficulty || "normal") === "normal" ? "selected" : ""}>普通</option><option value="hard" ${t.eventDifficulty === "hard" ? "selected" : ""}>困难</option></select>\n          </div>\n          <div class="pw-switch-row">\n            <div class="info"><b>🧭 推进模式</b><small>动态=整轮初始化后一次请求只改几个模块（省token）；旧模式=每轮整轮重写（慢但稳定）</small></div>\n            <select id="pw-advance-mode" style="min-width:200px"><option value="two_phase" ${t.advanceMode !== "legacy_full" ? "selected" : ""}>单请求动态推进（默认）</option><option value="legacy_full" ${t.advanceMode === "legacy_full" ? "selected" : ""}>每次更新所有事件（旧模式）</option></select>\n          </div>\n          <div style="display:grid;grid-template-columns:1fr 1fr;gap:7px">\n            <div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap;padding:8px 10px;border:1px solid rgba(63,185,232,.14);border-radius:9px;background:rgba(127,220,255,.02);font-size:10.5px;color:#7692a0">\n              ⚡ 单次动态最多\n              <input id="pw-dynamic-max" type="number" min="1" max="24" value="${escapeHtml(t.dynamicMaxModules || 4)}" style="width:56px;text-align:center;background:rgba(255,255,255,.04);border:1px solid rgba(63,185,232,.2);border-radius:6px;color:#d7e7f0;padding:4px 6px;font-size:11px;font-family:inherit">\n              个模块\n            </div>\n            <div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap;padding:8px 10px;border:1px solid rgba(63,185,232,.14);border-radius:9px;background:rgba(127,220,255,.02);font-size:10.5px;color:#7692a0">\n              📜 一次推进发送\n              <input id="pw-chat-history-limit" type="text" placeholder="留空=all" value="${escapeHtml(t.chatHistoryLimit === "" || t.chatHistoryLimit == null ? "" : String(t.chatHistoryLimit))}" style="width:70px;text-align:center;background:rgba(255,255,255,.04);border:1px solid rgba(63,185,232,.2);border-radius:6px;color:#d7e7f0;padding:4px 6px;font-size:11px;font-family:inherit">\n              楼记录\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <div class="pw-vcard gold">\n        <div class="pw-vcard-header"><h3>🎚️ 生成规模参数</h3><span class="meta">共 8 项</span></div>\n        <div class="pw-cfg">\n          <label><b>🧩 每轮生成模块数 (3-24)</b><input id="pw-module-count" type="number" min="3" max="24" value="${escapeHtml(t.moduleCount || 8)}"></label>\n          <label><b>✨ 细节程度</b><select id="pw-detail-level"><option value="extreme_concise" ${t.detailLevel === "extreme_concise" ? "selected" : ""}>极度简洁</option><option value="concise" ${t.detailLevel === "concise" ? "selected" : ""}>简洁</option><option value="normal" ${t.detailLevel === "normal" ? "selected" : ""}>适中</option><option value="detailed" ${t.detailLevel === "detailed" ? "selected" : ""}>详细</option></select></label>\n          <label><b>📝 事件字数下限</b><input id="pw-event-word-min" type="number" min="20" max="5000" value="${escapeHtml(t.eventWordMin || 100)}"></label>\n          <label><b>📝 事件字数上限</b><input id="pw-event-word-max" type="number" min="20" max="5000" value="${escapeHtml(t.eventWordMax || 800)}"></label>\n          <label><b>💉 最多注入模块数</b><input id="pw-max-inject-modules" type="number" min="1" max="50" value="${escapeHtml(t.maxInjectModules)}"></label>\n          <label><b>⚠️ 最多强制事件数</b><input id="pw-max-urgent-events" type="number" min="1" max="10" value="${escapeHtml(t.maxUrgentEvents || 3)}"></label>\n          <label><b>🌪 后台影响主线强度</b><select id="pw-impact-mode"><option value="soft" ${t.impactMode === "soft" ? "selected" : ""}>柔和·只作背景</option><option value="normal" ${t.impactMode === "normal" ? "selected" : ""}>正常·自然影响</option><option value="strong" ${t.impactMode === "strong" ? "selected" : ""}>强·高危必须进入主线</option><option value="force" ${t.impactMode === "force" ? "selected" : ""}>强制·危急事件打断主线</option></select></label>\n          <label><b>⏱ 自动推进延迟 ms</b><input id="pw-auto-delay" type="number" min="300" max="20000" value="${escapeHtml(t.autoDelayMs)}"></label>\n        </div>\n      </div>\n\n      <div class="pw-vcard green" style="margin-bottom:0">\n        <div class="pw-vcard-header"><h3>📝 用户指南 · 平行世界补充要求</h3><span class="meta">后台世界推进方向引导</span></div>\n        <textarea id="pw-user-guide" rows="5" style="width:100%;padding:11px 13px;background:rgba(0,0,0,.3);border:1px solid rgba(88,212,163,.18);border-radius:9px;color:#bfd7e5;font-family:inherit;font-size:11.5px;line-height:1.75;box-sizing:border-box;outline:none;resize:vertical" placeholder="例如：更重视城市政治、让远方勇者线独立推进、不要让NPC围着主角转……">${escapeHtml(t.userGuide)}</textarea>\n      </div>\n    </section>\n\n    \x3c!-- ===== TAB6: API+标签 ===== --\x3e\n    <section class="pw-tab-pane" data-pwpane="adv">\n      <div class="m-head"><span class="mico">🤖</span><h2>高级 · API 自定义 & 上下文标签过滤</h2></div>\n\n      <div class="pw-vcard">\n        <div class="pw-vcard-header"><h3>🤖 平行世界 API 配置</h3><span class="meta">单独模型 · 省主模型 token</span></div>\n        <div class="pw-cfg">\n          <label class="full"><b>API 来源</b><select id="pw-api-type"><option value="current" ${t.apiType === "current" ? "selected" : ""}>随主模型</option><option value="custom" ${t.apiType === "custom" ? "selected" : ""}>自定义 OpenAI 兼容 API</option></select></label>\n          <label class="pw-custom-api" style="display:${t.apiType === "custom" ? "flex" : "none"}"><b>代理预设</b><select id="pw-proxy-preset">${pwGetPresetOptionsHtml(t.customApi.proxyPreset)}</select></label>\n          <label class="pw-custom-api" style="display:${t.apiType === "custom" ? "flex" : "none"}"><b>模型</b>\n            <div style="display:flex;gap:6px"><input id="pw-model" type="text" value="${escapeHtml(t.customApi.model || "")}" style="flex:1"><button class="pw-vbtn pw-vbtn-ghost" id="pw-fetch-models" style="flex:0 0 auto;padding:6px 10px">获取模型</button></div>\n          </label>\n          <select id="pw-model-select" class="pw-custom-api" style="display:${t.apiType === "custom" ? "block" : "none"};margin-bottom:7px">${pwModelOptionsHtml(t.customApi.model)}</select>\n          <label class="pw-custom-api" style="display:${t.apiType === "custom" ? "flex" : "none"}"><b>API 地址</b><input id="pw-api-url" type="text" value="${escapeHtml(t.customApi.apiurl || "")}"></label>\n          <label class="pw-custom-api" style="display:${t.apiType === "custom" ? "flex" : "none"}"><b>API Key</b><input id="pw-api-key" type="password" value="${escapeHtml(t.customApi.key || "")}"></label>\n        </div>\n        <details class="pw-custom-api" style="display:${t.apiType === "custom" ? "block" : "none"};margin-top:10px">\n          <summary style="cursor:pointer;color:#7fdcff;font-size:11.5px;font-weight:700">⚙️ 高级参数（温度 / 最大token / Top P / 惩罚）</summary>\n          <div class="pw-cfg" style="margin-top:9px">\n            <label><b>温度 temperature</b><input id="pw-temperature" type="number" step="0.1" value="${escapeHtml(t.customApi.temperature ?? "")}"></label>\n            <label><b>最大 token</b><input id="pw-max-tokens" type="number" step="128" value="${escapeHtml(t.customApi.max_tokens ?? "")}"></label>\n            <label><b>Top P</b><input id="pw-top-p" type="number" step="0.01" value="${escapeHtml(t.customApi.top_p ?? "")}"></label>\n            <label><b>频率惩罚</b><input id="pw-freq-pen" type="number" step="0.01" value="${escapeHtml(t.customApi.frequency_penalty ?? "")}"></label>\n            <label><b>存在惩罚</b><input id="pw-pres-pen" type="number" step="0.01" value="${escapeHtml(t.customApi.presence_penalty ?? "")}"></label>\n          </div>\n        </details>\n        <div class="pw-custom-api" style="display:${t.apiType === "custom" ? "block" : "none"};margin-top:9px">\n          ${ssRenderJsonFormatControls("pw", t.customApi.extraBodyParamsYaml)}\n          ${ssRenderExtraParamsPanelHtml("pw", { extraBodyParamsYaml: t.customApi.extraBodyParamsYaml, excludeBodyParamsYaml: t.customApi.excludeBodyParamsYaml, extraHeadersYaml: t.customApi.extraHeadersYaml }, { accent: "#7fdcff", border: "rgba(63,185,232,.20)", bg: "rgba(255,255,255,0.018)", inputBg: "rgba(255,255,255,0.04)", inputBorder: "rgba(63,185,232,.25)", labelColor: "#7692a0", hintColor: "#7692a0", textColor: "#d7e7f0" })}\n          <div style="display:flex;gap:6px;margin-top:8px;flex-wrap:wrap;align-items:center">\n            <select id="pw-saved-api-select" style="flex:1;min-width:180px;max-width:100%">${ssGetCustomApiPresetOptionsHtml()}</select>\n            <button class="pw-vbtn pw-vbtn-ghost" id="pw-saved-api-apply">填入</button>\n            <button class="pw-vbtn pw-vbtn-ghost" id="pw-saved-api-save">保存</button>\n            <button class="pw-vbtn pw-vbtn-danger" id="pw-saved-api-delete">删除</button>\n          </div>\n        </div>\n      </div>\n\n      <div class="pw-vcard purple" style="margin-bottom:0">\n        <div class="pw-vcard-header"><h3>🏷️ 上下文标签过滤</h3><span class="meta">chatHistory 读取时过滤</span></div>\n        <div class="pw-switch-row" style="margin-bottom:10px">\n          <div class="info"><b>🏷️ 启用平行世界标签过滤</b><small>开启后会按下方规则过滤上下文；关闭=直接读原生 chat_history</small></div>\n          <div class="pw-sw ${t.enableContentFilter !== false ? "on" : ""}" id="pw-content-filter-sw" data-pwcheck="pw-content-filter"></div>\n          <input type="checkbox" id="pw-content-filter" ${t.enableContentFilter !== false ? "checked" : ""} style="display:none">\n        </div>\n        <div style="font-size:10.5px;color:#547182;line-height:1.65;margin-bottom:10px">\n          默认已排除 <code style="color:#9cd7ea">&lt;stage_2_pre_output_check&gt;</code>、<code style="color:#9cd7ea">&lt;think_fox~&gt;</code>、<code style="color:#9cd7ea">&lt;fox_tip&gt;</code>、<code style="color:#9cd7ea">&lt;fox_selc&gt;</code> 等内部检查块。<br>\n          左边=开始标签，右边=结束标签；允许只填结束标签（例：填 <code style="color:#9cd7ea">&lt;/think_fox~&gt;</code> = 删除它之前的所有内容）。\n        </div>\n        <div class="pw-sub-t" style="margin:6px 0 8px"><small>✅ 包含标签（只保留这些标签范围内的内容）</small></div>\n        ${ssCreateTagPairsEditorHtml("pw-inc", "✅ 包含标签", Array.isArray(t.includeTagPairs) ? t