  function enhanceDashboardUI() {
    const e = R.getElementById("ss-dashboard");
    if (!e) return;
    injectFoxUiPolish();
    if (e.classList.contains("xh-workbench")) {
      e.querySelectorAll(".ss-dashboard-section-title").forEach((e) =>
        e.classList.add("ss-section-title"),
      );
      e.querySelectorAll(".ss-dashboard-section-box").forEach((e) =>
        e.classList.add("ss-section-box"),
      );
      const t = R.getElementById("ss-dash-status");
      if (t && !t.dataset.polished) {
        t.dataset.polished = "1";
        t.title = "当前思维链样式 / 展开状态 / 可见状态";
      }
      return;
    }
    const t = [...e.children];
    for (let e = 1; e < t.length; e += 2) {
      const n = t[e];
      const o = t[e + 1];
      if (!n) continue;
      n.classList.add("ss-section-title");
      if (o) {
        o.classList.add("ss-section-box");
        const e = (n.textContent || "").trim();
        if (e.includes("快捷开关")) o.classList.add("ss-quick-grid");
        if (e.includes("预设选项控制")) o.classList.add("ss-preset-grid");
        if (e.includes("上下文管理")) o.classList.add("ss-context-row");
      }
    }
    const n = R.getElementById("ss-dash-status");
    if (n && !n.dataset.polished) {
      n.dataset.polished = "1";
      n.title = "当前思维链样式 / 展开状态 / 可见状态";
    }
  }
  function enhanceHushenUI() {
    const e = R.getElementById("ss-hushen-panel");
    if (!e) return;
    injectFoxUiPolish();
    const t = [...e.querySelectorAll(".ss-hushen-input")];
    t.forEach((e, t) => {
      const n = e.closest('div[style*="background"]');
      if (!n || n.classList.contains("ss-hushen-card")) return;
      n.classList.add("ss-hushen-card");
      const o = R.createElement("span");
      o.className = "ss-hushen-index";
      o.textContent = String(t + 1).padStart(2, "0");
      n.appendChild(o);
    });
    const n = e.querySelector("#ss-hushen-analyze-all")?.parentElement;
    if (n) n.classList.add("ss-hushen-actions");
  }
  function enhanceHusouUI() {
    const e = R.getElementById("ss-husou-panel");
    if (!e) return;
    injectFoxUiPolish();
    // ✅ §5.2：原实现取 firstElementChild，但 getHusouPanelHtml 返回串以 <style> 开头，
    //   ⇒ t 永远是 <style>、[...t.children] 为空 ⇒ 这段卡片分类永远空转（死代码）。
    const t =
      e.querySelector(".pc-head")?.nextElementSibling ??
      e.querySelector(".hs-tab-pane > div") ??
      e.querySelector(".work");
    if (!t) return;
    [...t.children].forEach((e) => {
      const t = e.textContent || "";
      if (
        t.includes("总开关") ||
        t.includes("搜索参数") ||
        t.includes("搜索来源") ||
        t.includes("请求 API") ||
        t.includes("搜索预设") ||
        t.includes("管理注入内容")
      ) {
        e.classList.add("ss-husou-card");
      }
    });
    polishHusouCheckboxes(e);
    foldHusouCustomSearchAdvanced(e);
  }
  function applyDashboardMode() {
    const e = R.getElementById("ss-dashboard");
    if (!e) return;
    const t = r.getItem(f.DASHBOARD_MODE_KEY) !== "advanced";
    const n = [
      "思维链控制",
      "快捷开关",
      "实用工具",
      "预设选项控制",
      "杀八股",
      "自定义内容编辑",
      "大总结",
      "拷打模式",
      "狐析",
      "狐裁",
      "配置备份",
    ];
    if (e.classList.contains("xh-workbench")) return;
    const o = [
      ...e.querySelectorAll(
        ":scope > .ss-dashboard-section-title, :scope > [data-section-title]",
      ),
    ];
    for (const a of o) {
      const o = a.nextElementSibling;
      const r = String(a.dataset.sectionTitle || a.textContent || "").trim();
      const s = !t || n.some((e) => r.includes(e));
      if (a.dataset.ssDashboardDisplay == null)
        a.dataset.ssDashboardDisplay = a.style.display || "";
      a.style.display = s ? a.dataset.ssDashboardDisplay : "none";
      if (o && o !== e.firstElementChild) {
        if (o.dataset.ssDashboardDisplay == null)
          o.dataset.ssDashboardDisplay = o.style.display || "";
        o.style.display = s ? o.dataset.ssDashboardDisplay : "none";
      }
    }
    if (t) {
      const t = new Set();
      for (const e of o.filter((e) =>
        n.some((t) => (e.textContent || "").includes(t)),
      )) {
        t.add(e);
        if (e.nextElementSibling) t.add(e.nextElementSibling);
      }
      for (const n of [...e.children]) {
        if (n === e.firstElementChild || t.has(n)) continue;
        if (n.dataset.ssDashboardDisplay == null)
          n.dataset.ssDashboardDisplay = n.style.display || "";
        n.style.display = "none";
      }
    } else {
      for (const t of [...e.children]) {
        if (t.dataset.ssDashboardDisplay != null)
          t.style.display = t.dataset.ssDashboardDisplay;
      }
    }
  }
  function reorderDashboardSections() {
    const e = R.getElementById("ss-dashboard");
    if (!e) return;
    if (e.classList.contains("xh-workbench")) {
      applyDashboardMode();
      return;
    }
    const t = e.firstElementChild;
    if (!t) return;
    e.querySelectorAll(
      ".ss-extra-separator-title, .ss-extra-separator-box",
    ).forEach((e) => e.remove());
    const n = [];
    const o = [...e.children];
    for (let e = 1; e < o.length; e++) {
      const t = o[e];
      const a = o[e + 1];
      if (!t || !a) continue;
      const r = (t.textContent || "").trim();
      if (
        r.includes("思维链控制") ||
        r.includes("快捷开关") ||
        r.includes("实用工具") ||
        r.includes("预设选项控制") ||
        r.includes("杀八股") ||
        r.includes("自定义内容编辑") ||
        r.includes("大总结") ||
        r.includes("拷打模式") ||
        r.includes("狐构") ||
        r.includes("狐忆") ||
        r.includes("狐裁") ||
        r.includes("狐析") ||
        r.includes("狐搜") ||
        r.includes("平行世界") ||
        r.includes("小说模式") ||
        r.includes("配置备份")
      ) {
        n.push({ title: t, box: a, text: r });
        e++;
      }
    }
    const a = [
      "思维链控制",
      "快捷开关",
      "实用工具",
      "预设选项控制",
      "杀八股",
      "自定义内容编辑",
      "大总结",
      "拷打模式",
      "狐构",
      "狐忆",
      "狐裁",
      "狐析",
      "狐搜",
      "平行世界",
      "小说模式",
      "配置备份",
    ];
    const r = new Set();
    function take(e) {
      const t = n.find((t) => !r.has(t) && t.text.includes(e));
      if (t) r.add(t);
      return t;
    }
    const s = [];
    for (const e of a) {
      const t = take(e);
      if (t) s.push(t);
    }
    for (const e of n) {
      if (!r.has(e)) s.push(e);
    }
    for (const t of s) {
      e.appendChild(t.title);
      e.appendChild(t.box);
    }
    applyDashboardMode();
  }
  function polishHusouCheckboxes(e) {
    if (!e) return;
    e.querySelectorAll("label").forEach((e) => {
      const t = e.querySelector('input[type="checkbox"]');
      if (!t || e.dataset.ssSwitchified === "1") return;
      e.dataset.ssSwitchified = "1";
      e.style.display = "flex";
      e.style.alignItems = "center";
      e.style.justifyContent = "space-between";
      e.style.gap = "10px";
      if (!e.classList.contains("husou-setting-row"))
        e.classList.add("husou-setting-row");
      t.style.display = "none";
      const n = R.createElement("span");
      n.className = "ss-husou-switch";
      n.setAttribute("role", "switch");
      n.setAttribute(
