(min-width:721px){#ft-panel .ft-mb-dock{display:none!important}}\n    </style>\n\n    <header class="ft-hd">\n      <div class="ft-crumb">🦊 模块中心 <i>▸</i> <b>狐刻</b></div>\n      <div class="ft-hd-right">狐刻总开关 <div class="ft-sw${e.enabled ? " on" : ""}" data-ft-enabled></div></div>\n      <button class="ft-x" data-close title="关闭">✕</button>\n    </header>\n    <div class="ft-work">\n      <aside class="ft-rail">\n        <div class="ft-rl-title">狐刻模块</div>\n        <div class="ft-mitem cur" data-tab="overview"><span class="ft-mico">📊</span><div class="ft-mtext"><b>概览</b><small>时钟 · 操作 · 阶段</small></div></div>\n        <div class="ft-mitem" data-tab="nodes"><span class="ft-mico">⚡</span><div class="ft-mtext"><b>节点表</b><small>触发节点管理</small></div></div>\n        <div class="ft-mitem" data-tab="kv"><span class="ft-mico">📈</span><div class="ft-mtext"><b>数值表</b><small>键值对数据</small></div></div>\n        <div class="ft-mitem" data-tab="config"><span class="ft-mico">⚙️</span><div class="ft-mtext"><b>配置</b><small>解析 · API · 开关</small></div></div>\n        <button id="ft-tl-toggle-btn" class="ft-btn ft-btn-ghost" style="margin-top:4px;white-space:nowrap;font-size:11px;padding:7px 12px;">📌 悬浮窗</button>\n        <div class="ft-clock-mini">\n          <div class="cm-label">📅 当前剧情时间</div>\n          <div class="cm-time">${a.unknown ? "⏳ 未知" : l(ftClockLabel(a))}</div>\n          <div class="cm-meta"><span>置信 <b>${l(a.confidence || "-")}</b></span><span>楼层 <b>#${a.updatedFloor ?? "-"}</b></span></div>\n        </div>\n      </aside>\n      <main class="ft-main">\n        <section class="ft-pane active" data-pane="overview">\n          <div class="ft-mhead"><span class="ft-mico">📊</span><h2>概览</h2><span class="ft-pill ${e.enabled ? "on" : "off"}">${e.enabled ? "运行中" : "未启用"}</span></div>\n          <div class="ft-chips"><span>时间权威</span><span>到点强制注入</span><span>混合式解析</span><span>快照回退</span></div>\n          <div class="ft-clock">\n            <div class="cc-label">📅 当前剧情时间</div>\n            <div class="cc-time">${a.unknown ? "⏳ 时间未知" : l(ftClockLabel(a))}</div>\n            <div class="cc-meta">\n              <div class="item"><span class="lb">置信度</span><span class="vl">${l(a.confidence || "-")}</span></div>\n              <div class="item"><span class="lb">更新楼层</span><span class="vl">#${a.updatedFloor ?? "-"}</span></div>\n              <div class="item"><span class="lb">绝对分钟</span><span class="vl">${a.unknown ? "-" : ftClockAbs(a)}</span></div>\n            </div>\n            <div class="cc-stats">\n              <span class="stat"><span class="dot gold"></span>节点 <b>${r.length}</b></span>\n              ${u ? `<span class="stat"><span class="dot fox"></span>到点 <b>${u}</b></span>` : ""}\n              ${f ? `<span class="stat"><span class="dot green"></span>已触发 <b>${f}</b></span>` : ""}\n            </div>\n          </div>\n          <div class="ft-subt">操作 <small>建立 / 解析 / 修正 / 刷新 / 清空</small></div>\n          <div class="ft-cfg"><div class="full acts">\n            <button data-act="build" class="ft-btn ft-btn-primary">🕰️ 建立时间轴</button>\n            <button data-act="parse" class="ft-btn ft-btn-ghost">⚡ 立即解析</button>\n            <button data-act="correct" class="ft-btn ft-btn-ghost">🔧 立即修正</button>\n            <button data-act="refresh" class="ft-btn ft-btn-ghost">🔄 刷新</button>\n            <span style="flex:1"></span>\n            <button data-act="clear" class="ft-btn ft-btn-danger">🗑️ 清空数据</button>\n          </div></div>\n          <div id="ft-status-msg" class="ft-status-msg"></div>\n          <div class="ft-subt">阶段表 <small>当前剧情阶段序列</small></div>\n          <div class="ft-tbl"><div style="overflow-x:auto;"><table><thead><tr><th>ID</th><th>阶段序列</th><th>当前</th></tr></thead><tbody>${c}</tbody></table></div></div>\n        </section>\n        <section class="ft-pane" data-pane="nodes">\n          <div class="ft-mhead"><span class="ft-mico">⚡</span><h2>节点表</h2><span class="ft-pill gold">${r.length} 个节点</span></div>\n          <div class="ft-chips"><span>pending ${r.filter((e) => e.status === "pending").length}</span><span>due ${u}</span><span>fired ${f}</span></div>\n          <div class="ft-subt">触发节点列表 <small>按时间顺序排列</small></div>\n          <div class="ft-tbl"><div style="overflow-x:auto;"><table><thead><tr><th style="width:40px">#</th><th>名称</th><th style="width:90px">状态</th><th style="width:80px">触发</th></tr></thead><tbody>${d}</tbody></table></div></div>\n          <div class="ft-note" style="margin-top:14px"><b>节点状态说明：</b>待触发（金色）= 未到时间；到点（橙色·呼吸）= 已到时间待注入；已触发（绿色）= 已注入正文；阶段（紫色）= 剧情阶段标记。</div>\n        </section>\n        <section class="ft-pane" data-pane="kv">\n          <div class="ft-mhead"><span class="ft-mico">📈</span><h2>数值表</h2><span class="ft-pill on">${Object.keys(i).length} 项</span></div>\n          <div class="ft-subt">键值对数据 <small>由解析 AI 提取的数值变量</small></div>\n          <div class="ft-tbl"><div style="overflow-x:auto;"><table><thead><tr><th>键</th><th style="width:120px">值</th><th style="width:100px">来源</th></tr></thead><tbody>${p}</tbody></table></div></div>\n        </section>\n        <section class="ft-pane" data-pane="config">\n          <div class="ft-mhead"><span class="ft-mico">⚙️</span><h2>配置</h2><span style="flex:1"></span><button data-act="savecfg" class="ft-btn ft-btn-primary">💾 保存配置</button></div>\n          <div class="ft-subt">基础配置 <small>解析模式 · 范围 · 间隔</small></div>\n          <div class="ft-cfg">\n            <label>解析模式<select data-cfg="parseMode"><option value="hybrid" ${e.parseMode === "hybrid" ? "selected" : ""}>混合式</option><option value="always_ai" ${e.parseMode === "always_ai" ? "selected" : ""}>每楼AI</option><option value="batch" ${e.parseMode === "batch" ? "selected" : ""}>攒批</option></select></label>\n            <label>解析范围<select data-cfg="parseScope"><option value="all" ${e.parseScope === "all" ? "selected" : ""}>全文（过滤后）</option><option value="head" ${e.parseScope === "head" ? "selected" : ""}>前N字</option><option value="tag" ${e.parseScope === "tag" ? "selected" : ""}>仅标签内</option></select></label>\n            <label>前N字限制<input data-cfg="parseHeadLimit" type="number" value="${e.parseHeadLimit ?? 800}" min="0" max="99999"></label>\n            <label>修正间隔（楼）<input data-cfg="correctInterval" type="number" value="${e.correctInterval}"></label>\n            <label>楼层限制（发送AI）<input data-cfg="contextFloors" type="number" value="${e.contextFloors ?? 50}" min="1" max="9999"></label>\n            <label>注入节点上限<input data-cfg="injectMaxNodes" type="number" value="${e.injectMaxNodes}"></label>\n            <label>强制注入上限<input data-cfg="injectMaxDue" type="number" value="${e.injectMaxDue}"></label>\n            <label>MVU联动<select data-cfg="mvuLink"><option value="auto" ${e.mvuLink === "auto" ? "selected" : ""}>双向</option><option value="readonly" ${e.mvuLink === "readonly" ? "selected" : ""}>只读</option><option value="off" ${e.mvuLink === "off" ? "selected" : ""}>关闭</option></select></label>\n            <label>API<select data-cfg="apiType"><option value="current" ${e.apiType === "current" ? "selected" : ""}>随主AI</option><option value="custom" ${e.apiType === "custom" ? "selected" : ""}>自定义</option></select></label>\n            <label class="full">解析起始标签<input data-cfg="parseTagStart" type="text" value="${l(e.parseTagStart || "<content>")}" placeholder="<content>"></label>\n            <label class="full">解析结束标签<input data-cfg="parseTagEnd" type="text" value="${l(e.parseTagEnd || "</content>")}" placeholder="</content>"></label>\n          </div>\n          <div id="ft-custom-api-wrap" style="display:${e.apiType === "custom" ? "block" : "none"}">\n            <details class="ft-codebox" id="ft-custom-api-details" ${e.apiType === "custom" ? "open" : ""}>\n              <summary>🌐 自定义API配置</summary>\n              <div class="ft-cfg" style="border:0;padding:12px 13px 0">\n                <label class="full">代理预设（优先）<select data-cfg="customApi.proxyPreset"><option value="">留空=直连自定义地址</option>${(() => {
      let t = "";
      try {
        const n = getFn("getPresetNames");
        if (typeof n === "function") {
          for (const o of n()
            .filter((e) => e !== "in_use")
            .sort()) {
            t += `<option value="${l(o)}" ${e.customApi?.proxyPreset === o ? "selected" : ""}>${l(o)}</option>`;
          }
        }
      } catch {}
      return t;
    })()}</select></label>\n                <label class="full">API地址<input data-cfg="customApi.apiurl" type="text" value="${l(e.customApi?.apiurl || "")}" placeholder="https://.../v1"></label>\n                <label>密钥<input data-cfg="customApi.key" type="password" value="${l(e.customApi?.key || "")}" placeholder="sk-..."></label>\n                <label>模型<input data-cfg="customApi.model" type="text" value="${l(e.customApi?.model || "")}" placeholder="模型名"></label>\n                <label>模型列表<select id="ft-api-model-select"><option value="">（点击右侧获取）</option>${(as.models || []).map((t) => `<option value="${l(t)}"${t === e.customApi?.model ? " selected" : ""}>${l(t)}</option>`).join("")}</select></label>\n                <label>&nbsp;<button id="ft-fetch-models" class="ft-btn ft-btn-ghost" style="width:100%;font-size:11px;padding:6px 10px;">${as.loadingModels ? "加载中…" : "获取模型列表"}</button></label>\n                <label>温度<input data-cfg="customApi.temperature" type="text" value="${l(e.customApi?.temperature || "")}" placeholder="留空=默认"></label>\n                <label>最大token<input data-cfg="customApi.max_tokens" type="text" value="${l(e.customApi?.max_tokens || "")}" placeholder="留空=默认"></label>\n                <label>top_p<input data-cfg="customApi.top_p" type="text" value="${l(e.customApi?.top_p || "")}" placeholder="留空=默认"></label>\n                <label>频率惩罚<input data-cfg="customApi.frequency_penalty" type="text" value="${l(e.customApi?.frequency_penalty || "")}" placeholder="留空=默认"></label>\n                <label>存在惩罚<input data-cfg="customApi.presence_penalty" type="text" value="${l(e.customApi?.presence_penalty || "")}" placeholder="留空=默认"></label>\n              </div>\n              ${ssRenderExtraParamsPanelHtml("ft", e.customApi || {})}\n              <div style="display:flex;gap:6px;margin:8px 13px;padding:0 0 8px;flex-wrap:wrap;align-items:center;">\n                <select id="ft-saved-api-select" style="flex:1;min-width:160px;box-sizing:border-box;background:rgba(0,0,0,.3);border:1px solid rgba(255,255,255,.07);border-radius:7px;color:#e8ddd4;padding:6px 9px;font-size:11px;">${ssGetCustomApiPresetOptionsHtml()}</select>\n                <button id="ft-saved-api-apply" class="ft-btn ft-btn-ghost" style="font-size:11px;padding:6px 10px;">填入</button>\n                <button id="ft-saved-api-save" class="ft-btn ft-btn-ghost" style="font-size:11px;padding:6px 10px;">保存</button>\n                <button id="ft-saved-api-delete" class="ft-btn ft-btn-danger" style="font-size:11px;padding:6px 10px;">删除</button>\n              </div>\n            </details>\n          </div>\n          <div class="ft-subt">开关</div>\n          <div class="ft-cfg">\n            <label class="ft-check"><input data-cfg="pwGate" type="checkbox" ${e.pwGate ? "checked" : ""}> 平行世界硬门闩</label>\n            <label class="ft-check"><input data-cfg="injectEnabled" type="checkbox" ${e.injectEnabled ? "checked" : ""}> 注入正文</label>\n            <label class="ft-check"><input data-cfg="silentCorrect" type="checkbox" ${e.silentCorrect ? "checked" : ""}> 静默修正</label>\n          </div>\n          <div class="ft-cfg" style="margin-top:8px;">${xhSendAnalyzeBtnHtml("ft-send-analyze", e.sendAnalyze === true)}</div>\n          <div class="ft-subt">标签过滤 <small>狐刻上下文标签</small></div>\n          <details class="ft-codebox">\n            <summary>🏷️ 狐刻上下文标签过滤（包含/排除）</summary>\n            ${(() => {
      const t = ssNormalizeTagFilterSettings(e);
      return `<div style="padding:10px 13px;font-size:11px;color:#8a7f78;line-height:1.6;">过滤狐刻AI分析时读取的上下文内容。默认排除 &lt;think_fox~&gt; / &lt;fox_selc&gt; / &lt;fox_tip&gt; 标签。</div>\n              <div style="padding:0 13px 12px"><label class="ft-check" style="margin-bottom:8px"><input type="checkbox" id="ft-content-filter" ${t.enableContentFilter !== false ? "checked" : ""}> 启用标签过滤</label>\n              ${ssCreateTagPairsEditorHtml("ft-inc", "✅ 包含标签：只保留这些标签范围内的内容", t.includeTagPairs, "一行一组：开始标签 + 结束标签")}\n              ${ssCreateTagPairsEditorHtml("ft-exc", "❌ 排除标签：删除这些标签范围内的内容", t.excludeTagPairs, "允许只填结束标签，例如结束填 </think_fox~> = 删除它之前所有内容。")}\n              </div>`;
    })()}\n          </details>\n          <div class="ft-note info" style="margin-top:14px"><b>配置说明：</b>解析模式决定时间轴建立方式；混合式优先用正则提取，失败时回退 AI。MVU 联动可将狐刻数值同步到 MVU 模块。标签过滤控制哪些上下文标签参与解析。</div>\n        </section>\n      </main>\n    </div>\n    <nav class="ft-mb-dock" style="display:none">\n      <div class="ft-mb-dock-item cur" data-mbtab="overview"><div class="ft-mb-ic">📊</div><div class="ft-mb-t">概览</div></div>\n      <div class="ft-mb-dock-item" data-mbtab="nodes"><div class="ft-mb-ic">⚡</div><div class="ft-mb-t">节点</div></div>\n      <div class="ft-mb-dock-item" data-mbtab="kv"><div class="ft-mb-ic">📈</div><div class="ft-mb-t">数值</div></div>\n      <div class="ft-mb-dock-item" data-mbtab="config"><div class="ft-mb-ic">⚙️</div><div class="ft-mb-t">配置</div></div>\n      <div class="ft-mb-dock-item" id="ft-mb-tl-toggle"><div class="ft-mb-ic">📌</div><div class="ft-mb-t">悬浮窗</div></div>\n    </nav>\n    `;
    R.body.appendChild(n);
    R.body.appendChild(o);
    n.addEventListener("click", ftClosePanel);
    o.querySelector("[data-close]")?.addEventListener("click", ftClosePanel);
    let m = false;
    const ftSwitchTab = (e, t) => {
      if (m) return;
      const n = o.querySelector(".ft-pane.active");
      if (n && n.dataset.pane === e) return;
      m = true;
      if (t) t();
      if (n) {
        n.classList.add("leaving");
        setTimeout(() => {
          n.classList.remove("active", "leaving");
          const t = o.querySelector(`.ft-pane[data-pane="${e}"]`);
          if (t) t.classList.add("active");
          m = false;
        }, 170);
      } else {
        m = false;
      }
    };
    o.querySelectorAll(".ft-mitem[data-tab]").forEach((e) => {
      e.addEventListener("click", () => {
        ftSwitchTab(e.dataset.tab, () => {
          o.querySelectorAll(".ft-mitem").forEach((e) =>
            e.classList.remove("cur"),
          );
          e.classList.add("cur");
        });
      });
    });
    o.querySelectorAll(".ft-mb-dock-item[data-mbtab]").forEach((e) => {
      e.addEventListener("click", () => {
        ftSwitchTab(e.dataset.mbtab, () => {
          o.querySelectorAll(".ft-mb-dock-item").forEach((e) =>
            e.classList.remove("cur"),
          );
          e.classList.add("cur");
        });
      });
    });
    o.querySelector("[data-ft-enabled]")?.addEventListener(
      "click",
      function () {
        const e = as.config || ftLoadConfig();
        e.enabled = !e.enabled;
        ftSaveConfig(e);
        as.config = e;
        this.classList.toggle("on", e.enabled);
        const t = o.querySelector(".ft-pill");
        if (t) {
          t.className = `ft-pill ${e.enabled ? "on" : "off"}`;
          t.textContent = e.enabled ? "运行中" : "未启用";
        }
        try {
          ftRegisterAutoListener();
        } catch {}
        try {
          if (e.enabled) {
            if (
              typeof ftTimelineGetOpenPref === "function" &&
              ftTimelineGetOpenPref()
            ) {
              if (typeof ftTimelineMount === "function" && !is.el)
                ftTimelineMount();
            }
          } else {
            if (typeof ftTimelineUnmount === "function" && is.el)
              ftTimelineUnmount();
          }
        } catch (e) {
          log("[狐刻] 总开关联动悬浮窗失败", e);
        }
        try {
