          if (t) t.classList.toggle("cur", !!is.el);
        } catch {}
        toast(
          e.enabled ? "🕰️ 狐刻已启用" : "🕰️ 狐刻已关闭",
          e.enabled ? "success" : "info",
        );
      },
    );
    const x = o.querySelector("#ft-tl-toggle-btn");
    if (x) {
      x.textContent = is.el ? "📌 悬浮窗 ✓" : "📌 悬浮窗";
      x.addEventListener("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        ftTimelineToggle();
