      if (panel === xhPcPanel) {
        const previous =
          action === "preview" ? panel.querySelector(`[data-preview="${value}"]`) : null;
        const previewText = previous && !previous.hidden ? previous.textContent : null;
        xhPcRenderManager();
        for (const select of panel.querySelectorAll("[data-rollback-source]"))
          if (Object.prototype.hasOwnProperty.call(rollbackSources, select.dataset.rollbackSource))
            select.value = rollbackSources[select.dataset.rollbackSource];
        if (action === "rollback-options")
          panel.querySelector("[data-rollback]")?.scrollIntoView({ block: "nearest" });
        const next = previewText != null ? panel.querySelector(`[data-preview="${value}"]`) : null;
